function jortSort(array) {
    // sort the array
    let sortedArray = array.slice();
    sortedArray.sort();
 
    // compare to see if it was originally sorted
    for (let i = 0; i < array.length; i++) {
        if (array[i]!== sortedArray[i]) {
            return false;
        }
    }
 
    return true;
}

