const Hffs = function() {
    this.sequence_r = {};
    this.sequence_s = {};
};
 
Hffs.prototype.ffr = function(n) {
    // first try the cache
    let new_r = this.sequence_r[n] || (n === 0? 1 : this.ffr(n - 1) + this.ffs(n - 1));
 
    // insert into the cache and return value
    return this.sequence_r[n] = new_r;
};
 
Hffs.prototype.ffs = function(n) {
    // first try the cache
    let new_s = this.sequence_s[n] || (n === 0? 2 : {
        let lower = this.ffs(n - 1) + 1;
        let upper = this.ffr(n) + 1;
        let min_s = 0;
        // find next available S
        for (let i = lower; i <= upper; i++) {
            if (!Object.values(this.sequence_r).includes(i)) {
                min_s = i;
                break;
            }
        }
        min_s;
    });
 
    // insert into the cache and return value
    return this.sequence_s[n] = new_s;
};
 
