function tokenizeString(s, sep, escape) {
    var tokens = [];
    var sb = [];
    var inEscape = false;
    for (var i = 0; i < s.length; i++) {
        var c = s[i];
        if (inEscape) {
            inEscape = false;
        } else if (c == escape) {
            inEscape = true;
            continue;
        } else if (c == sep) {
            tokens.push(sb.join(''));
            sb = [];
            continue;
        }
        sb.push(c);
    }
    if (inEscape)
        throw new Error("Invalid terminal escape");
    tokens.push(sb.join(''));
    return tokens;
}
 
