var ShellSorter = (function () {
    function ShellSorter() {
    }
    ShellSorter.Sort = function (list) {
        var n = list.length;
        var h = 1;
        while (h < (n >> 1)) {
            h = (h << 1) + 1;
        }
        while (h >= 1) {
            for (var i = h; i < n; i++) {
                var k = i - h;
                for (var j = i; j >= h && list[j].CompareTo(list[k]) < 0; k -= h) {
                    var temp = list[j];
                    list[j] = list[k];
                    list[k] = temp;
                    j = k;
                }
            }
            h >>= 1;
        }
    };
    return ShellSorter;
}());

