var smallNumbers = [
  "zero", "one", "two", "three", "four", "five",
  "six", "seven", "eight", "nine", "ten",
  "eleven", "twelve", "thirteen", "fourteen", "fifteen",
  "sixteen", "seventeen", "eighteen", "nineteen"
];
 
function spellHundreds(n) {
  var res = "";
  if (n > 99) {
    res = smallNumbers[Math.floor(n/100)];
    res += " hundred";
    n %= 100;
    if (n) res += " and ";
  }
  if (n >= 20) {
    var Decades = [
      "", "", "twenty", "thirty", "forty",
      "fifty", "sixty", "seventy", "eighty", "ninety"
    ];
    res += Decades[Math.floor(n/10)];
    n %= 10;
    if (n) res += "-";
  }
  if (n < 20 && n > 0)
    res += smallNumbers[n];
  return res;
}
 
 
var thousandPowers = [
  " billion", " million",  " thousand", "" ];
 
function spell(n) {
  if (n < 20) return smallNumbers[n];
  var res = "";
  var pScaleName = thousandPowers;
  var scaleFactor = 1000000000;	// 1 billion
  while (scaleFactor > 0) {
    if (n >= scaleFactor) {
      var h = Math.floor(n / scaleFactor);
      res += spellHundreds(h) + pScaleName;
      n %= scaleFactor;
      if (n) res += ", ";
    }
    scaleFactor /= 1000;
    ++pScaleName;
  }
  return res;
}
 
function spell_it(x) {
  console.log(x + " " + spell(x));
}
 
