var N = 5;
 
function generate_square() {
  var perms = [];
  for (var i = 1; i <= N; i++) {
    perms.push(i);
  }
  perms = shuffle(perms);
  var square = [];
  for (var i = 0; i < N; i++) {
    square.push(perms.pop());
    perms = perms.filter(function(perm) {
      return perm.map(function(el, j) {
        return el == square[i][j];
      }).indexOf(true) == -1;
    });
  }
  return square;
}
 
function print_square(square) {
  var cell_size = square.map(function(row) {
    return row.map(function(el) {
      return el.toString();
    });
  }).reduce(function(max, row) {
    return Math.max(max, row.reduce(function(max, el) {
      return Math.max(max, el.length);
    }, 0));
  }, 0) + 1;
  var strings = square.map(function(row) {
    return row.map(function(el) {
      return el.toString().padStart(cell_size,'');
    }).join('');
  });
  console.log(strings.join('\n') + '\n');
}
 
function shuffle(array) {
  var currentIndex = array.length, temporaryValue, randomIndex;
  while (0!== currentIndex) {
    randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex -= 1;
    temporaryValue = array[currentIndex];
    array[currentIndex] = array[randomIndex];
    array[randomIndex] = temporaryValue;
  }
  return array;
}
 
for (var i = 0; i < 2; i++) {
  print_square(generate_square());
}

