function show(x) {
	var i, j;
	for (i = 0; i < 9; i++) {
		if (!(i % 3)) console.log('\n');
		for (j = 0; j < 9; j++)
			console.log(j % 3? "%2d" : "%3d", x[i * 9 + j]);
		console.log('\n');
	}
}
 
function trycell(x, pos) {
	var row = Math.floor(pos / 9);
	var col = pos % 9;
	var i, j, used = 0;
 
	if (pos == 81) return 1;
	if (x[pos]) return trycell(x, pos + 1);
 
	for (i = 0; i < 9; i++)
		used |= 1 << (x[i * 9 + col] - 1);
 
	for (j = 0; j < 9; j++)
		used |= 1 << (x[row * 9 + j] - 1);
 
	row = Math.floor(row / 3) * 3;
	col = Math.floor(col / 3) * 3;
	for (i = row; i < row + 3; i++)
		for (j = col; j < col + 3; j++)
			used |= 1 << (x[i * 9 + j] - 1);
 
	for (x[pos] = 1; x[pos] <= 9; x[pos]++, used >>= 1)
		if (!(used & 1) && trycell(x, pos + 1)) return 1;
 
	x[pos] = 0;
	return 0;
}
 
function solve(s) {
	var i, x = [];
	for (i = 0; i < 81; i++)
		x[i] = s[i] >= '1' && s[i] <= '9'? s[i] - '0' : 0;
 
	if (trycell(x, 0))
		show(x);
	else
		console.log("no solution");
}
 
