var makehist = function(S, hist, len) {
	var wherechar = new Array(256);
	var i, histlen;
	histlen = 0;
	for (i = 0; i < 256; i++) {
		wherechar[i] = -1;
	}
	for (i = 0; i < len; i++) {
		if (wherechar[S[i]] == -1) {
			wherechar[S[i]] = histlen;
			histlen++;
		}
		hist[wherechar[S[i]]]++;
	}
	return histlen;
};
 
var entropy = function(hist, histlen, len) {
	var i;
	var H;
	H = 0;
	for (i = 0; i < histlen; i++) {
		H -= hist[i] / len * Math.log2(hist[i] / len);
	}
	return H;
};
 
var main = function() {
	var S = new Array(MAXLEN);
	var len, hist, histlen;
	var H;
	S = scanf("%[^\n]");
	len = S.length;
	hist = new Array(len);
	histlen = makehist(S, hist, len);
	//hist now has no order (known to the program) but that doesn't matter
	H = entropy(hist, histlen, len);
	printf("%lf\n", H);
};
 
