import { asList, emptyList, of } from 'java-util';
import { collect, flatMap, map, stream } from 'java-stream';
 
export function product(...a) {
    if (a.length >= 2) {
        let product = a[0];
        for (let i = 1; i < a.length; i++) {
            product = product(product, a[i]);
        }
        return product;
    }
 
    return emptyList();
}
 
function product(a, b) {
    return of(stream(a)
       .map(e1 => of(stream(b)
           .map(e2 => asList(e1, e2))
           .collect(toList()))
           .orElse(emptyList()))
       .flatMap(e => e)
       .collect(toList()))
       .orElse(emptyList());
}

