var switchWins = 0;
var stayWins = 0;

var gen = new Random();

for(var plays = 0; plays < 1000000; plays++ )
{
    var doors = [0,0,0];//0 is a goat, 1 is a car

    var winner = gen.Next(3);
    doors[winner] = 1; //put a winner in a random door

    var choice = gen.Next(3); //pick a door, any door
    var shown; //the shown door
    do
    {
        shown = gen.Next(3);
    }
    while (doors[shown] == 1 || shown == choice); //don't show the winner or the choice

    stayWins += doors[choice]; //if you won by staying, count it

    //the switched (last remaining) door is (3 - choice - shown), because 0+1+2=3
    switchWins += doors[3 - choice - shown];
}

console.log("Staying wins " + stayWins + " times.");
console.log("Switching wins " + switchWins + " times.");

const { Path } = require('svg.js')

function yin_yang(r, th) {
    const cr = ",0,1,1,.1,0z"
    const cw = ",0,0,1,0,"
    const ccw = ",0,0,0,0,"
    const d = `M0,${r + th} a${r},${r}${cr} M0,${-r / 3} ` // main_circle
        + `a${r},${r}${cr} m0,${r} a${r},${r}${cr} M0,0 ` // eyes
        + `A${r / 2},${r / 2}${ccw}${r} A${r},${r}${cw}-${r} A${r / 2},${r / 2}${cw}0` // yang
    return new Path(d).fill('none')
}

