var PartialApplication = (function () {
    "use strict";

    var IntegerFunction = function () {
    };

    IntegerFunction.prototype.call = function (arg) {
        throw new Error("Not implemented");
    };

    var SequenceFunction = function () {
    };

    SequenceFunction.prototype.call = function (arg) {
        throw new Error("Not implemented");
    };

    var fs = function (f, s) {
        var r = new Array(s.length);
        for (var i = 0; i < s.length; i++) {
            r[i] = f.call(s[i]);
        }
        return r;
    };

    var fs_f = function (f) {
        return new SequenceFunction() {
            call: function (s) {
                return fs(f, s);
            }
        };
    };

    var f1 = new IntegerFunction() {
        call: function (i) {
            return i * 2;
        }
    };

    var f2 = new IntegerFunction() {
        call: function (i) {
            return i * i;
        }
    };

    var fsf1 = fs_f(f1);

    var fsf2 = fs_f(f2);

    var main = function (args) {
        var sequences = [
            [0, 1, 2, 3],
            [2, 4, 6, 8]
        ];

        for (var array in sequences) {
            console.log("array: " + array);
            console.log("  fsf1(array): " + fsf1.call(array));
            console.log("  fsf2(array): " + fsf2.call(array));
        }
    };

    return {
        main: main
    };
})();

PartialApplication.main(process.argv.slice(2));

