// Based on https://www.cairographics.org/samples/gradient/
 
const { QImage, QPainter, QLinearGradient, QRadialGradient, QBrush, QRect, QRectF, Qt } = require('nodegui');
 
const main = () => {
    const black = new QColor(0, 0, 0);
    const white = new QColor(255, 255, 255);
 
    const size = 300;
    const diameter = 0.6 * size;
 
    const image = new QImage(size, size, QImage.Format_RGB32);
    const painter = new QPainter(image);
    painter.setRenderHint(QPainter.RenderHint.Antialiasing);
 
    const linearGradient = new QLinearGradient(0, 0, 0, size);
    linearGradient.setColorAt(0, white);
    linearGradient.setColorAt(1, black);
 
    const brush = new QBrush(linearGradient);
    painter.fillRect(new QRect(0, 0, size, size), brush);
 
    const point1 = new QPointF(0.4 * size, 0.4 * size);
    const point2 = new QPointF(0.45 * size, 0.4 * size);
    const radialGradient = new QRadialGradient(point1, size * 0.5, point2, size * 0.1);
    radialGradient.setColorAt(0, white);
    radialGradient.setColorAt(1, black);
 
    const brush2 = new QBrush(radialGradient);
    painter.setPen(Qt.PenStyle.NoPen);
    painter.setBrush(brush2);
    painter.drawEllipse(new QRectF((size - diameter)/2, (size - diameter)/2, diameter, diameter));
 
    image.save('sphere.png');
}
 
