var log2 = function(number) {
   return (Math.log(number) / Math.log(2));
};
 
var find_entropy = function(fiboword) {
   var frequencies = {};
   fiboword.split('').forEach(function(c) {
      if (frequencies[c]) {
         frequencies[c]++;
      } else {
         frequencies[c] = 1;
      }
   });
   var numlen = fiboword.length;
   var infocontent = 0;
   for (var p in frequencies) {
      var freq = frequencies[p] / numlen;
      infocontent += freq * log2(freq);
   }
   infocontent *= -1;
   return infocontent;
};
 
var printLine = function(fiboword, n) {
   console.log(n.toString().padStart(5,'') + fiboword.length.toString().padStart(12,'') + find_entropy(fiboword).toFixed(13).padStart(16,''));
};
 
