/* all ranking functions assume the array of Pairs is non-empty and already sorted by decreasing order of scores
   and then, if the scores are equal, by reverse alphabetic order of names
*/
 
function standardRanking(scores) {   
    var rankings = new Int32Array(scores.length);
    rankings[0] = 1;
    for (var i = 1; i < scores.length; i++) rankings[i] = scores[i].first == scores[i - 1].first? rankings[i - 1] : i + 1;
    return rankings;
}
 
function modifiedRanking(scores) {   
    var rankings = new Int32Array(scores.length);
    rankings[0] = 1; 
    for (var i = 1; i < scores.length; i++) {
        rankings[i] = i + 1; 
        var currScore = scores[i].first;         
        for (var j = i - 1; j >= 0; j--) {
            if (currScore!= scores[j].first) break;
            rankings[j] = i + 1;
        }       
    }
    return rankings;
}
 
function denseRanking(scores) {   
    var rankings = new Int32Array(scores.length);
    rankings[0] = 1;
    var prevRanking = 1;
    for (var i = 1; i < scores.length; i++) rankings[i] = scores[i].first == scores[i - 1].first? prevRanking : ++prevRanking;
    return rankings;
}
 
function ordinalRanking(scores) {   
    var rankings = new Int32Array(scores.length);
    for (var i = 0; i < scores.length; i++) rankings[i] = i + 1;
    return rankings;
}  
 
function fractionalRanking(scores) {
    var rankings = new Float64Array(scores.length);
    rankings[0] = 1.0; 
    for (var i = 1; i < scores.length; i++) {
        var k = i; 
        var currScore = scores[i].first;         
        for (var j = i - 1; j >= 0; j--) {
            if (currScore!= scores[j].first) break;
            k = j;
        }
        var avg = (k + 1 + i) / 2.0;
        for (var m = k; m <= i; m++) rankings[m] = avg;       
    }
    return rankings;
}    
 
function printRankings(title, rankings, scores) {
    console.log(title + ":");
    for (var i = 0; i < rankings.length; i++) { 
        console.log(rankings[i] + "  " + scores[i].toString().replace("(", "").replace(")", "").replace(",", ""));
    }
    console.log();
}
 
function printFractionalRankings(title, rankings, scores) {
    console.log(title + ":");
    for (var i = 0; i < rankings.length; i++) { 
        console.log(rankings[i].toFixed(2) + "  " + scores[i].toString().replace("(", "").replace(")", "").replace(",", ""));
    }
    console.log();
}
 
function main() {
    var scores = [[44, "Solomon"], [42, "Jason"], [42, "Errol"], [41, "Garry"], [41, "Bernard"], [41, "Barry"], [39, "Stephen"]];
    printRankings("Standard ranking", standardRanking(scores), scores);
    printRankings("Modified ranking", modifiedRanking(scores), scores);
    printRankings("Dense ranking", denseRanking(scores), scores);
    printRankings("Ordinal ranking", ordinalRanking(scores), scores);
    printFractionalRankings("Fractional ranking", fractionalRanking(scores), scores);
}
 
