function Transpose( m )
{
	var t = new Array( m[0].length );
	for( var i=0; i<t.length; i++ )
		t[i] = new Array( m.length );
 
for( var i=0; i<m.length; i++ )
	for( var j=0; j<m[i].length; j++ )
		t[j][i] = m[i][j];			
 
return t;
}

