import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';

@Component({
  selector: 'app-fibonacci-word-fractal',
  templateUrl: './fibonacci-word-fractal.component.html',
  styleUrls: ['./fibonacci-word-fractal.component.css']
})
export class FibonacciWordFractalComponent implements OnInit {
  @ViewChild('canvas', { static: true })
  canvas: ElementRef<HTMLCanvasElement>;
  ctx: CanvasRenderingContext2D;
  wordFractal: string;

  constructor() { }

  ngOnInit() {
    this.ctx = this.canvas.nativeElement.getContext('2d');
    this.wordFractal = this.wordFractal(23);
    this.drawWordFractal(20, 20, 1, 0);
  }

  wordFractal(n: number): string {
    if (n < 2) {
      return n === 1? '1' : '';
    }

    // we should really reserve fib n space here
    let f1 = '1';
    let f2 = '0';

    for (n = n - 2; n > 0; n--) {
      const tmp = f2;
      f2 += f1;

      f1 = tmp;
    }

    return f2;
  }

  drawWordFractal(x: number, y: number, dx: number, dy: number) {
    for (let n = 0; n < this.wordFractal.length; n++) {
      this.ctx.beginPath();
      this.ctx.moveTo(x, y);
      this.ctx.lineTo(x + dx, y + dy);
      this.ctx.stroke();
      x += dx;
      y += dy;
      if (this.wordFractal.charAt(n) === '0') {
        const tx = dx;
        dx = (n % 2 === 0)? -dy : dy;
        dy = (n % 2 === 0)? tx : -tx;
      }
    }
  }
}

