function stemplot(stem) {
    var d = [];
    var interval = Math.pow(10, Math.floor(stem.leafdigits));
    for (var i = 0; i < stem.data.length; i++) {
        var data = stem.data[i];
        var stm = Math.floor(data / interval);
        var lf = data % interval;
        d.push([stm, lf]);
    }
    var stems = d.map(function(x) { return x[0]; });
    var leafs = d.map(function(x) { return x[1]; });
    var stemwidth = Math.max.apply(null, stems.map(function(x) { return x.toString().length; }));
    var leafwidth = Math.max.apply(null, leafs.map(function(x) { return x.toString().length; }));
    var laststem = Math.min.apply(null, stems) - 1;
    var out = [];
    for (var i = 0; i < d.length; i++) {
        var s = d[i][0];
        var l = d[i][1];
        while (laststem < s) {
            laststem += 1;
            out.push('\n' + (' '.repeat(stemwidth - laststem.toString().length)) + laststem +'|');
        }
        out.push(' ' + ('0'.repeat(leafwidth - l.toString().length)) + l);
    }
    out.push('\n\nKey:\n Stem multiplier: ' + interval + '\n X | Y  =>  ' + interval + '*X+Y\n');
    return out.join('');
}
 
