function countingSort(array, mn, mx) {
    var count = {};
    for (var i = 0; i < array.length; i++) {
        var num = array[i];
        count[num] = count[num]? count[num] + 1 : 1;
    }
    var result = [];
    for (var j = mn; j <= mx; j++) {
        while (count[j] > 0) {
            result.push(j);
            count[j]--;
        }
    }
    return result;
}

