const { range } = require('lodash');

const properDivsSum = (n) => {
  return range(1, (n + 1) / 2).filter(i => n!= i && n % i == 0).sum();
}

let deficient = 0;
let perfect = 0;
let abundant = 0;

for (let i = 1; i <= 20_000; i++) {
  const sum = properDivsSum(i);
  if (sum < i)
    deficient++;
  else if (sum == i)
    perfect++;
  else
    abundant++;
}
console.log("Deficient: " + deficient);
console.log("Perfect: " + perfect);
console.log("Abundant: " + abundant);

var Chaocipher = (function () {
    var Mode;
    (function (Mode) {
        Mode[Mode["ENCRYPT"] = 0] = "ENCRYPT";
        Mode[Mode["DECRYPT"] = 1] = "DECRYPT";
    })(Mode || (Mode = {}));
    var L_ALPHABET = "HXUCZVAMDSLKPEFJRIGTWOBNYQ";
    var R_ALPHABET = "PTLNBQDEOYSFAVZKGJRIHWXUMC";
    function indexOf(a, c) {
        for (var i = 0; i < a.length; ++i) {
            if (a[i] == c) {
                return i;
            }
        }
        return -1;
    }
    function exec(text, mode) {
        return exec(text, mode, false);
    }
    function exec(text, mode, showSteps) {
        var left = L_ALPHABET.split('');
        var right = R_ALPHABET.split('');
        var eText = new Array(text.length);
        var temp = new Array(26);
        for (var i = 0; i < text.length; ++i) {
            if (showSteps) {
                console.log(left.join(''), right.join(''));
            }
            var index;
            if (mode == Mode.ENCRYPT) {
                index = indexOf(right, text.charAt(i));
                eText[i] = left[index];
            }
            else {
                index = indexOf(left, text.charAt(i));
                eText[i] = right[index];
            }
            if (i == text.length - 1) {
                break;
            }
            // permute left
            if (26 - index >= 0)
                left.splice(0, 0, left.splice(index, 26 - index).join(''));
            var store = left[1];
            left.splice(1, 1);
            left.splice(13, 0, store);
            // permute right
            if (26 - index >= 0)
                right.splice(0, 0, right.splice(index, 26 - index).join(''));
            store = right[0];
            right.splice(0, 1);
            right.splice(25, 0, store);
            store = right[2];
            right.splice(2, 1);
            right.splice(13, 0, store);
        }
        return eText.join('');
    }
    function main() {
        var plainText = "WELLDONEISBETTERTHANWELLSAID";
        console.log("The original plaintext is : %s", plainText);
        console.log("\nThe left and right alphabets after each permutation during encryption are:");
        var cipherText = exec(plainText, Mode.ENCRYPT, true);
        console.log("\nThe cipher text is : %s", cipherText);
        var plainText2 = exec(cipherText, Mode.DECRYPT);
        console.log("\nThe recovered plaintext is : %s", plainText2);
    }
    return {
        main: main
    };
}());
Chaocipher.main();

