}
 
function main(n) {
	var i, j;
 
	//Edit: Input must be odd and not less than 3.
	if (n < 3 || (n%2) == 0) return 2;
 
	for (i = 0; i < n; i++) {
		for (j = 0; j < n; j++)
			print(f(n, n - j - 1, i)*n + f(n, j, i) + 1);
		print('\n');
	}
	print("\n Magic Constant: %d.\n", (n*n+1)/2*n);
 
	return 0;
}

function nth(num) {
    return num + (function() {
        switch (num % 10) {
            case 1:
                if (num % 100 === 11) {
                    return "th";
                }
                return "st";
            case 2:
                if (num % 100 === 12) {
                    return "th";
                }
                return "nd";
            case 3:
                if (num % 100 === 13) {
                    return "th";
                }
                return "rd";
            default:
                return "th";
        }
    })();
}
 
