class AngleDifference {
    static getDifference(b1, b2) {
        let r = (b2 - b1) % 360.0;
        if (r < -180.0)
            r += 360.0;
        if (r >= 180.0)
            r -= 360.0;
        return r;
    }

    static main(args) {
