var n = 100;
var nn = (n * (n + 1)) >> 1;
 
function Contains(lst, item, size) {
	for (var i = 0; i < size; i++) if (item == lst[i]) return true;
	return false;
}
 
function MianChowla() {
	var mc = new Array(n); mc[0] = 1;
	var sums = new Array(nn); sums[0] = 2;
	var sum, le, ss = 1;
	for (var i = 1; i < n; i++) {
		le = ss;
		for (var j = mc[i - 1] + 1; ; j++) {
			mc[i] = j;
			for (var k = 0; k <= i; k++) {
				sum = mc[k] + j;
				if (Contains(sums, sum, ss)) {
					ss = le; break;
				}
				sums[ss++] = sum;
			}
			break;
		}
	}
	return mc;
}
 
