var happy = function(number) {
  var cache = {};
  var cycle = {};
  while (number!= 1 &&!cycle[number]) {
    if (cache[number]) {
      number = cache[number]? 1 : 0;
      break;
    }
    cycle[number] = true;
    var newnumber = 0;
    while (number > 0) {
      var digit = number % 10;
      newnumber += digit * digit;
      number = Math.floor(number / 10);
    }
    number = newnumber;
  }
  var happiness = number == 1;
  for (var it in cycle)
    cache[it] = happiness;
  return happiness;
}
 
for (var i = 1; i < 50; i++)
  if (happy(i))
    console.log(i);

var Generator = function () {
};
 
// Does nothing unspecialized
var PowersGenerator = function () {
};
 
// Specialize with other types, or provide a generic version of pow
var PowersGenerator_int = function () {
  this.i = 1;
};
 
PowersGenerator_int.prototype = new Generator();
 
PowersGenerator_int.prototype.operator = function () {
  var o = 1;
  for (var j = 0; j < 2; ++j) {
    o *= this.i;
  }
  ++this.i;
  return o;
};
 
// Only works with non-decreasing generators
var Filter = function () {
  this.gen = new PowersGenerator_int();
  this.filter = new PowersGenerator_int();
  this.lastG = this.gen.operator();
  this.lastF = this.filter.operator();
};
 
Filter.prototype = new Generator();
 
Filter.prototype.operator = function () {
  while (this.lastG >= this.lastF) {
    if (this.lastG == this.lastF) {
      this.lastG = this.gen.operator();
    }
    this.lastF = this.filter.operator();
  }
  var out = this.lastG;
  this.lastG = this.gen.operator();
  return out;
};
 
var gen = new Filter();
 
for (var i = 0; i < 20; ++i) {
  gen.operator();
}
 
