function distance(p1, p2) {
    return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
}
 
function describe_circle(p1, p2, r) {
    var sep = distance(p1, p2);
 
    if (sep === 0) {
        if (r === 0) {
            console.log("No circles can be drawn through " + p1);
        } else {
            console.log("Infinitely many circles can be drawn through " + p1);
        }
    } else if (sep === 2 * r) {
        console.log("Given points are opposite ends of a diameter of the circle with center (" + (p1.x + p2.x) / 2 + ", " + (p1.y + p2.y) / 2 + ") and r " + r);
    } else if (sep > 2 * r) {
        console.log("Given points are farther away from each other than a diameter of a circle with r " + r);
    } else {
        var mirror_dist = Math.sqrt(Math.pow(r, 2) - Math.pow(sep / 2, 2));
 
        console.log("Two circles are possible.");
        console.log("Circle C1 with center (" + ((p1.x + p2.x) / 2 + mirror_dist * (p1.y - p2.y) / sep) + ", " + (p1.y + p2.y) / 2 + mirror_dist * (p2.x - p1.x) / sep + "), r " + r + " and Circle C2 with center (" + (p1.x + p2.x) / 2 - mirror_dist * (p1.y - p2.y) / sep + ", " + (p1.y + p2.y) / 2 - mirror_dist * (p2.x - p1.x) / sep + "), r " + r);
    }
}
 
