var ChatServer = function(port) {
  this.port = port;
  this.clients = [];
};
 
ChatServer.prototype.run = function() {
  var self = this;
  var server = require('net').createServer(function(socket) {
    new Client(socket, self);
  });
  server.listen(this.port);
};
 
ChatServer.prototype.registerClient = function(client) {
  for (var i = 0; i < this.clients.length; i++) {
    if (this.clients[i].clientName.toLowerCase() === client.clientName.toLowerCase()) {
      return false;
    }
  }
  this.clients.push(client);
  return true;
};
 
ChatServer.prototype.deregisterClient = function(client) {
  var wasRegistered = false;
  for (var i = 0; i < this.clients.length; i++) {
    if (this.clients[i] === client) {
      this.clients.splice(i, 1);
      wasRegistered = true;
      break;
    }
  }
  if (wasRegistered) {
    this.broadcast(client, '---'+ client.clientName +'left ---');
  }
};
 
ChatServer.prototype.getOnlineListCSV = function() {
  var sb = [];
  sb.push(this.clients.length +'user(s) online: ');
  for (var i = 0; i < this.clients.length; i++) {
    if (i > 0) {
      sb.push(', ');
    }
    sb.push(this.clients[i].clientName);
  }
  return sb.join('');
};
 
ChatServer.prototype.broadcast = function(fromClient, msg) {
  for (var i = 0; i < this.clients.length; i++) {
    var client = this.clients[i];
    if (client === fromClient) {
      continue;
    }
    client.write(msg + '\r\n');
  }
};
 
var Client = function(socket, server) {
  this.socket = socket;
  this.server = server;
  this.clientName = null;
  this.run();
};
 
Client.prototype.run = function() {
  var self = this;
  this.socket.setSendBufferSize(16384);
  this.socket.setTcpNoDelay(true);
  this.socket.on('data', function(data) {
    self.onData(data);
  });
  this.socket.on('end', function() {
    self.onEnd();
  });
  this.socket.on('error', function(err) {
    self.onError(err);
  });
  this.write('Please enter your name: ');
};
 
Client.prototype.onData = function(data) {
  var line = data.toString().trim();
  if (this.clientName === null) {
    if (line.length === 0) {
      this.write('A name is required. Please enter your name: ');
      return;
    }
    this.clientName = line;
    if (!this.server.registerClient(this)) {
      this.clientName = null;
      this.write('Name already registered. Please enter your name: ');
      return;
    }
    this.write(this.server.getOnlineListCSV() + '\r\n');
    this.server.broadcast(this, '+++'+ this.clientName +'arrived +++');
    return;
  }
  if (line.toLowerCase() === '/quit') {
    return;
  }
  this.server.broadcast(this, this.clientName + '>'+ line);
};
 
Client.prototype.onEnd = function() {
  this.server.deregisterClient(this);
};
 
Client.prototype.onError = function(err) {
  this.server.deregisterClient(this);
};
 
Client.prototype.write = function(msg) {
  this.socket.write(msg);
};
 
Client.prototype.equals = function(client) {
  return (client!== null) && (client instanceof Client) && (this.clientName!== null) && (client.clientName!== null) && this.clientName.toLowerCase() === client.clientName.toLowerCase();
};
 
