function isEsthetic(n, b) {
    if (n == 0) {
        return false;
    }
 
    i = n % b;
    n2 = Math.floor(n / b);
    while (n2 > 0) {
        j = n2 % b;
        if (Math.abs(i - j)!= 1) {
            return false;
        }
        n2 = Math.floor(n2 / b);
        i = j;
    }
    return true;
}
 
function listEsths(n, n2, m, m2, perLine, all) {
    esths = [];
    dfs = function (n, m, i) {
        if (n <= i && i <= m) {
            esths.push(i);
        }
        if (i == 0 || i > m) {
            return;
        }
        d = i % 10;
        i1 = i * 10 + d - 1;
        i2 = i1 + 2;
        if (d == 0) {
            dfs(n, m, i2);
        } else if (d == 9) {
            dfs(n, m, i1);
        } else {
            dfs(n, m, i1);
            dfs(n, m, i2);
        }
    };
 
    for (i = 0; i <= 9; i++) {
        dfs(n2, m2, i);
    }
 
    le = esths.length;
    console.log("Base 10: %d esthetic numbers between %d and %d:", le, n, m);
    if (all) {
        esths.forEach(function (esth, idx) {
            console.log("%d ", esth);
            if ((idx + 1) % perLine == 0) {
                console.log("\n");
            }
        });
        console.log("\n");
    } else {
        for (i = 0; i < perLine; i++) {
            console.log("%d ", esths[i]);
        }
        console.log("\n............\n");
        for (i = le - perLine; i < le; i++) {
            console.log("%d ", esths[i]);
        }
        console.log("\n");
    }
    console.log("\n");
}
 
function main() {
    for (b = 2; b <= 16; b++) {
        console.log("Base %d: %dth to %dth esthetic numbers:", b, 4 * b, 6 * b);
        n = 1;
        c = 0;
        while (c < 6 * b) {
            if (isEsthetic(n, b)) {
                c = c + 1;
                if (c >= 4 * b) {
                    console.log("%s ", n.toString(b));
                }
            }
            n = n + 1;
        }
        console.log("\n");
    }
    console.log("\n");
 
    listEsths(1000, 1010, 9999, 9898, 16, true);
    listEsths(1e8, 101010101, 13 * 1e7, 123456789, 9, true);
    listEsths(1e11, 101010101010, 13 * 1e10, 123456789898, 7, false);
    listEsths(1e14, 101010101010101, 13 * 1e13, 123456789898989, 5, false);
    listEsths(1e17, 101010101010101010, 13 * 1e16, 123456789898989898, 4, false);
}
 
