function halve(n) {
    return n / 2;
}
 
function double(n) {
    return n * 2;
}
 
function isEven(n) {
    return n % 2 == 0;
}
 
function ethiopianMultiply(x, y) {
    var xx = x;
    var yy = y;
    var sum = 0;
    while (xx >= 1) {
       if (!isEven(xx)) sum += yy;
       xx = halve(xx);
       yy = double(yy);
    }
    return sum;
}
 
