function split(str) {
	var last = str[0], result = new Array(3 * str.length), counter = result;
	for (var c = 0; c < str.length; c++) {
		if (str[c]!= last) {
			result.push(", ");
			counter += 2;
			last = str[c];
		}
		result.push(str[c]);
		counter++;
	}
	result.pop();
	return result.join("");
}

