var f = function(x) { return x * x * x - 3 * x * x + 2 * x; };
 
var step = 0.001; // Smaller step values produce more accurate and precise results
var start = -1;
var stop = 3;
var value = f(start);
var sign = (value > 0)? 1 : 0;
 
// Check for root at start
if (value == 0)
    console.log("Root found at " + start);
 
for (var x = start + step; x <= stop; x += step)
{
    value = f(x);
 
    if (((value > 0)? 1 : 0)!= sign)
        // We passed a root
        console.log("Root found near " + x);
    else if (value == 0)
        // We hit a root
        console.log("Root found at " + x);
 
    // Update our sign
    sign = (value > 0)? 1 : 0;
}

