function floydWarshall(weights, numVerticies) {
    var dist = [];
    for (var i = 0; i < numVerticies; i++) {
        dist[i] = [];
        for (var j = 0; j < numVerticies; j++) {
            dist[i][j] = Number.POSITIVE_INFINITY;
        }
    }
 
    for (var i = 0; i < weights.length; i++) {
        dist[weights[i][0] - 1][weights[i][1] - 1] = weights[i][2];
    }
 
    var next = [];
    for (var i = 0; i < numVerticies; i++) {
        next[i] = [];
        for (var j = 0; j < numVerticies; j++) {
            if (i!= j) {
                next[i][j] = j + 1;
            }
        }
    }
 
    for (var k = 0; k < numVerticies; k++) {
        for (var i = 0; i < numVerticies; i++) {
            for (var j = 0; j < numVerticies; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                    next[i][j] = next[i][k];
                }
            }
        }
    }
 
    printResult(dist, next);
}
 
function printResult(dist, next) {
    console.log("pair     dist    path");
    for (var i = 0; i < next.length; i++) {
        for (var j = 0; j < next[i].length; j++) {
            if (i!= j) {
                var u = i + 1;
                var v = j + 1;
                var path = u + " -> " + v + "    " + dist[i][j] + "     " + u;
                do {
                    u = next[u - 1][v - 1];
                    path += " -> " + u;
                } while (u!= v);
                console.log(path);
            }
        }
    }
}
 
var weights = [[1, 3, -2], [2, 1, 4], [2, 3, 3], [3, 4, 2], [4, 2, -1]];
var numVerticies = 4;
 
floydWarshall(weights, numVerticies);

