       .filter(x => x < 2200)
       .sort((a, b) => a - b);
}
 
function a094958_filter() {
    return [...Array(2200).keys()]
       .filter(n => ((n & (n - 1) == 0) || (n % 5 == 0 && ((n / 5) & (n / 5 - 1) == 0))))
}
 
function a094958_loop() {
    let v = [];
    for (let n = 0; n < 12; n++) {
        v.push(1 << n);
        if (5 * (1 << n) < 2200) {
            v.push(5 * (1 << n));
        }
    }
    v.sort((a, b) => a - b);
    return v;
}
 
