function valid(sailor, nuts) {
  for (var i = 0; i < sailor; i++) {
    if ((nuts % sailor)!== 1) {
      return false;
    }
    nuts -= 1 + Math.floor(nuts / sailor);
  }
  return nuts > 0 && nuts % sailor === 0;
}

[5, 6].forEach(function(sailor) {
  var n = sailor;
  while (!valid(sailor, n)) {
    n += 1;
  }
  console.log("\n" + sailor + " sailors => " + n + " coconuts");
  for (var i = 0; i < sailor + 1; i++) {
    var div = Math.floor(n / sailor);
    var mod = n % sailor;
    console.log("  " + [n, div, mod]);
    n -= 1 + div;
  }
});

var SqMx = (function () {
    function SqMx() {
    }
    SqMx.prototype.identity = function () {
        var m = new SqMx();
        for (var r = 0; r < this.MSize; r++) {
            for (var c = 0; c < this.MSize; c++) {
                m.a[r][c] = (r == c? 1 : 0);
            }
        }
        return m;
    };
    SqMx.prototype.toString = function () {
        var s = "";
        for (var i = 0; i < this.MSize; i++) {
            for (var j = 0; j < this.MSize; j++) {
                s += this.a[i][j] + ',';
            }
            s += '\n';
        }
        return s;
    };
    SqMx.prototype.multiply = function (b) {
        var d = new SqMx();
        for (var r = 0; r < this.MSize; r++) {
            for (var c = 0; c < this.MSize; c++) {
                d.a[r][c] = 0;
                for (var k = 0; k < this.MSize; k++) {
                    d.a[r][c] += this.a[r][k] * b.a[k][c];
                }
            }
        }
        return d;
    };
    return SqMx;
})();

