const fs = require('fs');
const readline = require('readline');
 
function check(err) {
    if (err) {
        throw err;
    }
}
 
function readWords(fileName) {
    const file = fs.createReadStream(fileName);
    const rl = readline.createInterface({
        input: file,
        crlfDelay: Infinity
    });
    const words = [];
    rl.on('line', (line) => {
        const word = line.trim().toLowerCase();
        if (word.length >= 3) {
            words.push(word);
        }
    });
    return new Promise((resolve, reject) => {
        rl.on('close', () => {
            resolve(words);
        });
        rl.on('error', (err) => {
            reject(err);
        });
    });
}
 
function rotate(runes) {
    const first = runes[0];
    runes.copyWithin(0, 1);
    runes[runes.length - 1] = first;
}
 
async function main() {
    const dicts = ['mit_10000.txt', 'unixdict.txt']; // local copies
    for (const dict of dicts) {
        console.log(`Using ${dict}:`);
        console.log();
        const words = await readWords(dict);
        const n = words.length;
        const used = {};
    outer:
        for (const word of words) {
            const runes = word.split('');
            const variants = [word];
            for (let i = 0; i < runes.length - 1; i++) {
                rotate(runes);
                const word2 = runes.join('');
                if (word === word2 || used[word2]) {
                    continue outer;
                }
                const ix = words.indexOf(word2);
                if (ix === -1 || words[ix]!== word2) {
                    continue outer;
                }
                variants.push(word2);
            }
            for (const variant of variants) {
                used[variant] = true;
            }
            console.log(variants);
        }
        console.log();
    }
}
 
main().catch((err) => {
    console.error(err);
});

