function find_abbreviations_length(command_table_text) {
    var command_table = {};
    var words = command_table_text.split(" ");
    for (var i = 0; i < words.length; i++) {
        var word = words[i];
        var abbr_len = 0;
        for (var j = 0; j < word.length; j++) {
            if (word[j].toUpperCase() == word[j]) {
                abbr_len++;
            }
        }
        if (abbr_len == 0) {
            abbr_len = word.length;
        }
        command_table[word] = abbr_len;
    }
    return command_table;
}
 
function find_abbreviations(command_table) {
    var abbreviations = {};
    for (var command in command_table) {
        var min_abbr_len = command_table[command];
        for (var l = min_abbr_len; l <= command.length; l++) {
            var abbr = command.substring(0, l).toLowerCase();
            abbreviations[abbr] = command.toUpperCase();
        }
    }
    return abbreviations;
}
 
function parse_user_string(user_string, abbreviations) {
    var user_words = user_string.split(" ");
    var commands = [];
    for (var i = 0; i < user_words.length; i++) {
        var user_word = user_words[i].toLowerCase();
        var command = abbreviations[user_word];
        if (command == undefined) {
            command = "*error*";
        }
        commands.push(command);
    }
    return commands.join(" ");
}
 
