function line_intersect(Ax1, Ay1, Ax2, Ay2, Bx1, By1, Bx2, By2) {
    // returns a (x, y) tuple or None if there is no intersection
    var d = (By2 - By1) * (Ax2 - Ax1) - (Bx2 - Bx1) * (Ay2 - Ay1);
    if (d) {
        var uA = ((Bx2 - Bx1) * (Ay1 - By1) - (By2 - By1) * (Ax1 - Bx1)) / d;
        var uB = ((Ax2 - Ax1) * (Ay1 - By1) - (Ay2 - Ay1) * (Ax1 - Bx1)) / d;
    } else {
        return;
    }
    if (!(0 <= uA <= 1 && 0 <= uB <= 1)) {
        return;
    }
    var x = Ax1 + uA * (Ax2 - Ax1);
    var y = Ay1 + uA * (Ay2 - Ay1);
    return [x, y];
}
 
