var Data = function(ptr, cells) {
    this.ptr = ptr;
    this.cells = cells;
};
 
var inc_ptr = function(next_cmd) {
    return function(data) {
        return next_cmd(new Data(data.ptr + 1, data.cells));
    };
};
 
var dec_ptr = function(next_cmd) {
    return function(data) {
        return next_cmd(new Data(data.ptr - 1, data.cells));
    };
};
 
var inc_cell = function(next_cmd) {
    return function(data) {
        var cells = data.cells;
        var ptr = data.ptr;
        var cell = cells[ptr] || 0;
        return next_cmd(new Data(data.ptr, Object.assign({}, cells, {
            [ptr]: cell + 1
        })));
    };
};
 
var dec_cell = function(next_cmd) {
    return function(data) {
        var cells = data.cells;
        var ptr = data.ptr;
        var cell = cells[ptr] || 0;
        return next_cmd(new Data(data.ptr, Object.assign({}, cells, {
            [ptr]: cell - 1
        })));
    };
};
 
var output_cell = function(next_cmd) {
    return function(data) {
        var cells = data.cells;
        var ptr = data.ptr;
        var cell = cells[ptr] || 0;
        console.log(cell);
        return next_cmd(data);
    };
};
 
var input_cell = function(next_cmd) {
    return function(data) {
        var cells = data.cells;
        var ptr = data.ptr;
        var cell = cells[ptr] || 0;
        return next_cmd(new Data(data.ptr, Object.assign({}, cells, {
            [ptr]: cell
        })));
    };
};
 
var if_loop = function(next_cmd, loop_cmd) {
    return function(data) {
        var cells = data.cells;
        var ptr = data.ptr;
        var cell = cells[ptr] || 0;
        return next_cmd(loop(data));
    };
};
 
var terminate = function(data) {
    return data;
};
 
var split_cmds = function(cmds) {
    var split = function(cmds, loop_cmds) {
        if (cmds.length === 0) {
            throw new Error("invalid commands: missing ]");
        }
        var cmd = cmds[0];
        var rest_cmds = cmds.slice(1);
        switch (cmd) {
            case '[':
                var _split_cmds = split_cmds(rest_cmds);
                var c = _split_cmds[0];
                var l = _split_cmds[1];
                return split(c, loop_cmds + '[' + l + ']');
            case ']':
                return [rest_cmds, loop_cmds];
            default:
                return split(rest_cmds, loop_cmds + cmd);
        }
    };
    return split(cmds, '');
};
 
var compile_cmds = function(cmds) {
    if (cmds.length === 0) {
        return terminate;
    }
    var cmd = cmds[0];
    var rest_cmds = cmds.slice(1);
    switch (cmd) {
        case '>':
            return inc_ptr(compile_cmds(rest_cmds));
        case '<':
            return dec_ptr(compile_cmds(rest_cmds));
        case '+':
            return inc_cell(compile_cmds(rest_cmds));
        case '-':
            return dec_cell(compile_cmds(rest_cmds));
        case '.':
            return output_cell(compile_cmds(rest_cmds));
        case ',':
            return input_cell(compile_cmds(rest_cmds));
        case '[':
            var _split_cmds = split_cmds(rest_cmds);
            var cmds = _split_cmds[0];
            var loop_cmds = _split_cmds[1];
            return if_loop(compile_cmds(cmds), compile_cmds(loop_cmds));
        case ']':
            throw new Error("invalid commands: missing [");
        default:
            return compile_cmds(rest_cmds);
    }
};
 
var compile_and_run = function(cmds, input) {
    var compiled_cmds = compile_cmds(cmds);
    console.log(compiled_cmds(new Data(0, {})));
};

var Pendulum = function(length) {
    this.angle = Math.PI / 2;
    this.length = length;
};
 
Pendulum.prototype.paint = function(g) {
    g.setColor(Color.WHITE);
    g.fillRect(0, 0, getWidth(), getHeight());
    g.setColor(Color.BLACK);
    var anchorX = getWidth() / 2, anchorY = getHeight() / 4;
    var ballX = anchorX + (int) (Math.sin(angle) * length);
    var ballY = anchorY + (int) (Math.cos(angle) * length);
    g.drawLine(anchorX, anchorY, ballX, ballY);
    g.fillOval(anchorX - 3, anchorY - 4, 7, 7);
    g.fillOval(ballX - 7, ballY - 7, 14, 14);
};
 
Pendulum.prototype.run = function() {
    var angleAccel, angleVelocity = 0, dt = 0.1;
    while (true) {
        angleAccel = -9.81 / length * Math.sin(angle);
        angleVelocity += angleAccel * dt;
        angle += angleVelocity * dt;
        repaint();
        try { Thread.sleep(15); } catch (InterruptedException ex) {}
    }
};
 
Pendulum.prototype.getPreferredSize = function() {
    return new Dimension(2 * length + 50, length / 2 * 3);
};
 
Pendulum.prototype.main = function(args) {
    var f = new JFrame("Pendulum");
    var p = new Pendulum(200);
    f.add(p);
    f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
    f.pack();
    f.setVisible(true);
    new Thread(p).start();
};

var selection = function(arr, k) {
    var n = arr.length;
    var i = 0;
    var j = n - 1;
    var pivot = arr[Math.floor(Math.random() * n)];
    while (i <= j) {
        while (arr[i] < pivot) {
            i++;
        }
        while (arr[j] > pivot) {
            j--;
        }
        if (i <= j) {
            var temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i++;
            j--;
        }
    }
    if (k <= j) {
        return selection(arr, k);
    }
    if (k >= i) {
        return selection(arr, k);
    }
    return arr[k];
};

