function line(x0, y0, x1, y1) {
  var dx = Math.abs(x1-x0), sx = x0<x1? 1 : -1;
  var dy = Math.abs(y1-y0), sy = y0<y1? 1 : -1; 
  var err = (dx>dy? dx : -dy)/2, e2;

  for(;;){
    setPixel(x0,y0);
    if (x0==x1 && y0==y1) break;
    e2 = err;
    if (e2 >-dx) { err -= dy; x0 += sx; }
    if (e2 < dy) { err += dx; y0 += sy; }
  }
}

function Node(value, prev_node) {
    this.value = value;
    this.prev_node = prev_node;
}
 
function lis(values) {
    var E = values.constructor;
    var NodePtr = Node;
    var ConstNodePtr = Node;
 
    var pileTops = [];
    var nodes = [];
    for (var i = 0; i < values.length; i++) {
        nodes.push(new Node(values[i], null));
    }
 
    // sort into piles
    var cur_node = 0;
    for (var cur_value = 0; cur_value < values.length; cur_value++, cur_node++)
    {
        var node = nodes[cur_node];
 
        // lower_bound returns the first element that is not less than 'node->value'
        var lb = pileTops.length;
        for (var i = 0; i < pileTops.length; i++) {
            if (pileTops[i].value < node.value) {
                lb = i;
                break;
            }
        }
 
        if (lb!= 0)
            node.prev_node = pileTops[lb - 1];
 
        if (lb == pileTops.length)
            pileTops.push(node);
        else
            pileTops[lb] = node;
    }
 
    // extract LIS from piles
    // note that LIS length is equal to the number of piles
    var result = [];
    var r = result.length;
    for (var node = pileTops[pileTops.length - 1]; node!= null; node = node.prev_node, r++)
        result[r] = node.value;
 
    return result;
}
 
function show_lis(values)
{
    var result = lis(values);
    for (var i = 0; i < result.length; i++) {
        console.log(result[i]);
    }
}
 
