function zigzag(n) {
    var l = [];
    for (var i = 0; i < n * n; i++) {
        l.push({
            x: i % n,
            y: Math.floor(i / n)
        });
    }
    l.sort(function(a, b) {
        if (a.x + a.y == b.x + b.y) {
            if ((a.x + a.y) % 2 == 0) {
                return a.x - b.x;
            } else {
                return a.y - b.y;
            }
        } else {
            return a.x + a.y - b.x - b.y;
        }
    });
    var result = [];
    for (var i = 0; i < n; i++) {
        result.push([]);
    }
    for (var i = 0; i < n * n; i++) {
        result[l[i].y][l[i].x] = i;
    }
    return result;
}
 
