function quicksort(A, len) {
  if (len < 2) return;
 
  var pivot = A[len / 2];
 
  var i, j;
  for (i = 0, j = len - 1; ; i++, j--) {
    while (A[i] < pivot) i++;
    while (A[j] > pivot) j--;
 
    if (i >= j) break;
 
    var temp = A[i];
    A[i]     = A[j];
    A[j]     = temp;
  }
 
  quicksort(A, i);
  quicksort(A.slice(i), len - i);
}
 
