function generate(n, i, c) {
    var s = [];
    for (var i = 0; i < n; i++) {
        s[i] = [];
        for (var j = 0; j < n; j++) {
            s[i][j] = "";
        }
    }
    var dir = 0;
    var y = Math.floor(n / 2);
    var x = y - 1;
    if (n % 2 == 0) {
        x = y - 1;
    } else {
        x = y;
    }
    for (var j = i; j <= n * n - 1 + i; j++) {
        if (isPrime(j)) {
            if (c == 0) {
                s[y][x] = ("   " + j).slice(-3);
            } else {
                s[y][x] = (" " + c + " ").slice(-3);
            }
        } else {
            s[y][x] = "---";
        }
        switch (dir) {
        case 0:
            if (x <= n - 1 && s[y - 1][x] == "" && j > i) {
                dir = 1;
            }
            break;
        case 1:
            if (s[y][x - 1] == "") {
                dir = 2;
            }
            break;
        case 2:
            if (x == 0 || s[y + 1][x] == "") {
                dir = 3;
            }
            break;
        case 3:
            if (s[y][x + 1] == "") {
                dir = 0;
            }
            break;
        }
        switch (dir) {
        case 0:
            x += 1;
            break;
        case 1:
            y -= 1;
            break;
        case 2:
            x -= 1;
            break;
        case 3:
            y += 1;
            break;
        }
    }
    for (var i = 0; i < n; i++) {
        console.log(s[i]);
    }
    console.log();
}
 
function isPrime(a) {
    if (a == 2) {
        return true;
    }
    if (a <= 1 || a % 2 == 0) {
        return false;
    }
    var max = Math.floor(Math.sqrt(a));
    for (var n = 3; n <= max; n += 2) {
        if (a % n == 0) {
            return false;
        }
    }
    return true;
}
 
