function collapse_string(val) {
    let output = "";
    let chars = val.split("");
    let i = 0;
    while (i < chars.length) {
        let c = chars[i];
        while (i < chars.length && chars[i] === c) {
            i += 1;
        }
        output += c;
    }
    return output;
}
 
