function nthroot(n, A, precision) {
    var x_0 = A / n; //step 1: make a while guess.
    var x_1 = 1;     //need it to exist before step 2
    while (true) {
        //step 2:
        x_0 = x_1;
        x_1 = (1 / n)*((n - 1)*x_0 + (A / (x_0 ** (n - 1))));
        if (x_0 == x_1) {
            return x_1;
        }
    }
}

const MAX = 120;
 
function isPrime(n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    if (n % 3 == 0) return n == 3;
    let d = 5;
    while (d * d <= n) {
        if (n % d == 0) return false;
        d += 2;
        if (n % d == 0) return false;
        d += 4;
    }
    return true;
}
 
function primeFactorCount(n) {
    if (n == 1) return 0;
    if (isPrime(n)) return 1;
    let count = 0;
    let f = 2;
    while (true) {
        if (n % f == 0) {
            count++;
            n /= f;
            if (n == 1) return count;
            if (isPrime(n)) f = n;
        } else if (f >= 3) {
            f += 2;
        } else {
            f = 3;
        }
    }
}
 
