function lcs(a, b) {
    if (a.length > b.length) {
        return lcs(b, a);
    }
    var res = "";
    for (var ai = 0; ai < a.length; ai++) {
        for (var len = a.length - ai; len > 0; len--) {
            for (var bi = 0; bi <= b.length - len; bi++) {
                if (a.regionMatches(ai, b, bi, len) && len > res.length) {
                    res = a.substring(ai, ai + len);
                }
            }
        }
    }
    return res;
}
