var D3Vector = function(a, b, c) {
    this.x = a;
    this.y = b;
    this.z = c;
};

D3Vector.prototype.dotproduct = function(rhs) {
    var scalar = this.x * rhs.x + this.y * rhs.y + this.z * rhs.z;
    return scalar;
};

D3Vector.prototype.crossproduct = function(rhs) {
    var a = this.y * rhs.z - this.z * rhs.y;
    var b = this.z * rhs.x - this.x * rhs.z;
    var c = this.x * rhs.y - this.y * rhs.x;
    var product = new D3Vector(a, b, c);
    return product;
};

D3Vector.prototype.triplevec = function(a, b) {
    return this.crossproduct(a.crossproduct(b));
};

D3Vector.prototype.triplescal = function(a, b) {
    return this.dotproduct(a.crossproduct(b));
};

D3Vector.prototype.toString = function() {
    return "(" + this.x + ", " + this.y + ", " + this.z + ")";
};

