use std::process;
use structopt::StructOpt;
use morse_code::{Config, Opt, run};
 
/// Core of the command-line binary.
///
/// By default expects input from stdin and outputs resulting morse code to stdout, but can also
/// read and/or write to files.
/// Use `morse_code --help` for more information about options.
fn main() {
    let opts = Opt::from_args();
    let mut config = Config::new(opts).unwrap_or_else(|err| {
        eprintln!("Problem parsing arguments: {}", err);
        process::exit(1);
    });
    if let Err(err) = run(&mut config) {
        eprintln!("Application error: {}", err);
        process::exit(2);
    }
}

function Positions(cells,...blocks) {
    if (cells < 0 || blocks == null || blocks.some(b => b < 1)) throw new RangeError();
    console.log(`${cells} cells with [${blocks.join(", ")}]`);
    if (blocks.reduce((a, b) => a + b) + blocks.length - 1 > cells) {
        console.log("No solution");
        return;
    }
    var spaces = new Array(blocks.length + 1);
    var total = -1;
    for (var i = 0; i < blocks.length; i++) {
        total += blocks[i] + 1;
        spaces[i+1] = total;
    }
    spaces[spaces.length - 1] = cells - 1;
    var sb = new Array(blocks.map(b => "#".repeat(b)).join(".").padEnd(cells, "."));
    Iterate(sb, spaces, spaces.length - 1, 0);
    console.log();
}
 
function Iterate(output, spaces, index, offset) {
    console.log(output.join(""));
    if (index <= 0) return;
    var count = 0;
    while (output[spaces[index] - offset]!= "#") {
        count++;
        output.splice(spaces[index], 1);
        output.splice(spaces[index-1], 0, ".");
        spaces[index-1]++;
        Iterate(output, spaces, index - 1, 1);
    }
    if (offset == 0) return;
    spaces[index-1] -= count;
    output.splice(spaces[index-1], count);
    output.splice(spaces[index] - count, 0, ".", count);
}
 
