function ms2(txt, sep) {
	if (!txt ||!sep) return [];
	var ans = m = [];
	for (m = re.finditer('(.*?)(?:' + '|'.join('('+re.escape(s)+')' for s in sep) + ')', txt); m; m = m.next()) {
		ans += [m.group(1), (m.lastindex-2, m.start(m.lastindex))];
	}
	if (m && txt[m.end(m.lastindex):]) {
		ans += [txt[m.end(m.lastindex):]];
	}
	return ans;
}

