function FourIsMagic() {
 
    for ( var n of [6, 60, 89, 300, 670, 2000, 2467, 20000, 24500,200000, 230000, 246571, 2300000, 2465712, 20000000, 24657123, 230000000, 245000000, -246570000, 123456789712345, 8777777777777777777, Number.MAX_VALUE]) {
        var magic = fourIsMagic(n);
        console.log(n + " = " + toSentence(magic));
    }
 
    function toSentence(s) {
        return s.substring(0,1).toUpperCase() + s.substring(1) + ".";
    }
 
    var nums = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", 
            "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
    ];
 
    var tens = ["zero", "ten", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"];
 
    function fourIsMagic(n) {
        if ( n == 4 ) {
            return numToString(n) + " is magic";
        }
        var result = numToString(n);
        return result + " is " + numToString(result.length) + ", " + fourIsMagic(result.length);
    }
 
    function numToString(n) {
        if ( n < 0 ) { 
            return "negative " + numToString(-n);
        }
        var index = n;
        if ( n <= 19 ) {
            return nums[index];
        }
        if ( n <= 99 ) {
            return tens[index/10] + (n % 10 > 0? " " + numToString(n % 10) : "");
        }
        var label = null;
        var factor = 0;
        if ( n <= 999 ) {
            label = "hundred";
            factor = 100;
        }
        else if ( n <= 999999) {
            label = "thousand";
            factor = 1000;
        }
        else if ( n <= 999999999) {
            label = "million";
            factor = 1000000;
        }
        else if ( n <= 999999999999) {
            label = "billion";
            factor = 1000000000;
        }
        else if ( n <= 999999999999999) {
            label = "trillion";
            factor = 1000000000000;
        }
        else if ( n <= 999999999999999999) {
            label = "quadrillion";
            factor = 1000000000000000;
        }
        else {
            label = "quintillion";
            factor = 1000000000000000000;
        }
        return numToString(n / factor) + " " + label + (n % factor > 0? " " + numToString(n % factor ) : "");
    }
 
}

