function comb(N, K) {
    var bitmask = new Array(K).fill(1);
    bitmask.length = N;
    bitmask.fill(0, K);
    do {
        for (var i = 0; i < N; ++i) {
            if (bitmask[i]) {
                console.log(i);
            }
        }
        console.log();
    } while (prev_permutation(bitmask));
}
 
function prev_permutation(bitmask) {
    var i = bitmask.length - 1;
    while (i > 0 && bitmask[i - 1] <= bitmask[i]) {
        i--;
    }
    if (i <= 0) {
        return false;
    }
    var j = bitmask.length - 1;
    while (bitmask[j] >= bitmask[i - 1]) {
        j--;
    }
    var temp = bitmask[i - 1];
    bitmask[i - 1] = bitmask[j];
    bitmask[j] = temp;
    j = bitmask.length - 1;
    while (i < j) {
        temp = bitmask[i];
        bitmask[i] = bitmask[j];
        bitmask[j] = temp;
        i++;
        j--;
    }
    return true;
}
 
