var HuffmanTree = function(freq) {
    this.frequency = freq;
};
 
HuffmanTree.prototype.compareTo = function(tree) {
    return this.frequency - tree.frequency;
};
 
var HuffmanLeaf = function(freq, val) {
    HuffmanTree.call(this, freq);
    this.value = val;
};
 
HuffmanLeaf.prototype = Object.create(HuffmanTree.prototype);
 
var HuffmanNode = function(l, r) {
    HuffmanTree.call(this, l.frequency + r.frequency);
    this.left = l;
    this.right = r;
};
 
HuffmanNode.prototype = Object.create(HuffmanTree.prototype);
 
var HuffmanCode = function() {
};
 
HuffmanCode.prototype.buildTree = function(charFreqs) {
    var trees = [];
    // initially, we have a forest of leaves
    // one for each non-empty character
    for (var i = 0; i < charFreqs.length; i++) {
        if (charFreqs[i] > 0) {
            trees.push(new HuffmanLeaf(charFreqs[i], String.fromCharCode(i)));
        }
    }
 
    assert(trees.length > 0);
    // loop until there is only one tree left
    while (trees.length > 1) {
        // two trees with least frequency
        var a = trees.shift();
        var b = trees.shift();
 
        // put into new node and re-insert into queue
        trees.push(new HuffmanNode(a, b));
    }
    return trees.shift();
};
 
HuffmanCode.prototype.printCodes = function(tree, prefix) {
    assert(tree!== null);
    if (tree instanceof HuffmanLeaf) {
        var leaf = tree;
 
        // print out character, frequency, and code for this leaf (which is just the prefix)
        console.log(leaf.value + "\t" + leaf.frequency + "\t" + prefix);
 
    } else if (tree instanceof HuffmanNode) {
        var node = tree;
 
        // traverse left
        prefix += '0';
        this.printCodes(node.left, prefix);
        prefix = prefix.slice(0, -1);
 
        // traverse right
        prefix += '1';
        this.printCodes(node.right, prefix);
        prefix = prefix.slice(0, -1);
    }
};
 
HuffmanCode.prototype.main = function() {
    var test = "this is an example for huffman encoding";
 
    // we will assume that all our characters will have
    // code less than 256, for simplicity
    var charFreqs = new Array(256);
    // read each character and record the frequencies
    for (var i = 0; i < test.length; i++) {
        var c = test.charCodeAt(i);
        if (charFreqs[c] === undefined) {
            charFreqs[c] = 0;
        }
        charFreqs[c]++;
    }
 
    // build tree
    var tree = this.buildTree(charFreqs);
 
    // print out results
    console.log("SYMBOL\tWEIGHT\tHUFFMAN CODE");
    this.printCodes(tree, "");
};
 
var huffmanCode = new HuffmanCode();
huffmanCode.main();

