// A Maybe Monad. Requires TypeScript >= 3.7 for type hints.
 
type Maybe<T> = {
  value: T | null;
  bind: (func: (value: T) => Maybe<any>) => Maybe<any>;
};
 
function Maybe<T>(value: T | null): Maybe<T> {
  return {
    value,
    bind: (func: (value: T) => Maybe<any>) => func(value),
  };
}
 
function plusOne(value: number | null): Maybe<number> {
  if (value!== null) {
    return Maybe(value + 1);
  }
  return Maybe(null);
}
 
function currency(value: number | null): Maybe<string> {
  if (value!== null) {
    return Maybe(`$${value}.00`);
  }
  return Maybe(null);
}
 
const testCases = [1, 99, null, 4];
 
for (const testCase of testCases) {
  const mInt = Maybe(testCase);
  const result = mInt.bind(plusOne).bind(currency);
  console.log(`${testCase} -> ${result.value}`);
}

function MeanAngle(angles) {
    var x = angles.reduce((a, b) => a + Math.cos(b * Math.PI / 180), 0) / angles.length;
    var y = angles.reduce((a, b) => a + Math.sin(b * Math.PI / 180), 0) / angles.length;
    return Math.atan2(y, x) * 180 / Math.PI;
}
