function search(part, offset) {
    if (offset > maxPathLength) {
        maxPathLength = offset
        maxPathLengthCount = 1
    }
    else if (offset == maxPathLength) {
        maxPathLengthCount++
        maxPathExample.setLength(0)
        for (var i = 0; i < offset; i++) {
            maxPathExample.append(i % 5 == 0? "\n  " : " ")
            maxPathExample.append(part[i])
        }    
    }
    var lastChar = part[offset - 1].charAt(part[offset - 1].length - 1)
    for (var i = offset; i < part.length; i++) {
        if (part[i].charAt(0) == lastChar) {
            var tmp = names[offset]
            names[offset] = names[i]
            names[i] = tmp
            search(names, offset + 1)
            names[i] = names[offset]
            names[offset] = tmp
        }
    }
}
 
function main(args) {
    for (var i = 0; i < names.length; i++) {
        var tmp = names[0]
        names[0] = names[i]
        names[i] = tmp
        search(names, 1)
        names[i] = names[0]
        names[0] = tmp
    }
    console.log("Maximum path length         : " + maxPathLength)
    console.log("Paths of that length        : " + maxPathLengthCount)
