function anyvalidcomb(items, maxwt, val=0, wt=0) {
   'All combinations below the maxwt '
    if (!items) {
        return [[], val, wt];
    } else {
        this,...items = items;
        for (n = 0; n <= this.number; n++) {
            w = wt  + n * this.weight;
            if (w > maxwt) {
                break;
            }
            v = val + n * this.value;
            this_comb = [this] * n;
            for (comb, value, weight in anyvalidcomb(items, maxwt, v, w)) {
                yield this_comb + comb, value, weight;
            }
        }
    }
}
 
