// Translate this
 #include <boost/spirit.hpp>
 #include <boost/spirit/tree/ast.hpp>
 #include <string>
 #include <cassert>
 #include <iostream>
 #include <istream>
 #include <ostream>
 
 using boost::spirit::rule;
 using boost::spirit::parser_tag;
 using boost::spirit::ch_p;
 using boost::spirit::real_p;
 
 using boost::spirit::tree_node;
 using boost::spirit::node_val_data;
 
 // The grammar
 var parser = function() {
   this.addsub_id = 0;
   this.multdiv_id = 1;
   this.value_id = 2;
   this.real_id = 3;
   this.tmp = 0;
 };
 
 parser.prototype.set_value = function(node, begin, end) {
   node.value.value(this.tmp);
 };
 
 parser.prototype.definition = function() {
   this.addsub = this.multdiv
     >> *((root_node_d[ch_p('+')] | root_node_d[ch_p('-')]) >> multdiv);
   this.multdiv = value
     >> *((root_node_d[ch_p('*')] | root_node_d[ch_p('/')]) >> value);
   this.value = real | inner_node_d[('(' >> addsub >> ')')];
   this.real = leaf_node_d[access_node_d[real_p[assign_a(this.tmp)]][set_value(this)]];
 };
 
 parser.prototype.start = function() {
   return this.addsub;
 };
 
 var evaluate = function(i) {
   var op1, op2;
   switch (i.value.id().to_long()) {
   case parser.real_id:
     return i.value.value();
   case parser.value_id:
   case parser.addsub_id:
   case parser.multdiv_id:
     op1 = evaluate(i.children.begin());
     op2 = evaluate(i.children.begin()+1);
     switch(*i.value.begin()) {
     case '+':
       return op1 + op2;
     case '-':
       return op1 - op2;
     case '*':
       return op1 * op2;
     case '/':
       return op1 / op2;
     default:
       assert(!"Should not happen");
     }
   default:
     assert(!"Should not happen");
   }
   return 0;
 };
 
 // the read/eval/write loop
 var main = function() {
   var eval = new parser();
   var line;
   while (console.log("Expression: ")
          && (line = console.readline())
          &&!line.empty()) {
     var info =
       boost::spirit::ast_parse<factory_t>(line.begin(), line.end(),
                                           eval, boost::spirit::space_p);
     if (info.full) {
       console.log("Result: " + evaluate(info.trees.begin()));
     } else {
       console.log("Error in expression.");
     }
   }
 };

function mean_angle(deg) {
    var sum = 0;
    for (var i = 0; i < deg.length; i++) {
        sum += deg[i];
    }
    return sum / deg.length;
}
 
function mean_time(times) {
    var seconds = [];
    for (var i = 0; i < times.length; i++) {
        var time = times[i].split(':');
        seconds.push(time[0] * 3600 + time[1] * 60 + time[2] * 1);
    }
    var day = 24 * 60 * 60;
    var to_angles = [];
    for (var i = 0; i < seconds.length; i++) {
        to_angles.push(seconds[i] * 360. / day);
    }
    var mean_as_angle = mean_angle(to_angles);
    var mean_seconds = mean_as_angle * day / 360.;
    if (mean_seconds < 0) {
        mean_seconds += day;
    }
    var h = Math.floor(mean_seconds / 3600);
    var m = Math.floor((mean_seconds - h * 3600) / 60);
    var s = Math.floor(mean_seconds - h * 3600 - m * 60);
    return (h < 10? '0' + h : h) + ':' + (m < 10? '0' + m : m) + ':' + (s < 10? '0' + s : s);
}
 
