function prime(a) {
  if (a === 2) {
    return true;
  } else if (a <= 1 || a % 2 === 0) {
    return false;
  } else {
    var divisors = (3..Math.sqrt(a)).step(2);
    return divisors.none(function(d) {
      return a % d === 0;
    });
  }
}

