var balanced = function(str, left, right) {
    if (left === undefined) {
        left = '[';
    }
    if (right === undefined) {
        right = ']';
    }
    var count = 0;
    for (var i = 0; i < str.length; i++) {
        if (str[i] === left) {
            count++;
        } else if (str[i] === right) {
            if (--count < 0) {
                return false;
            }
        }
    }
    return count === 0;
};
 
