function dupf(v) {
	var ret = new ArrayBuffer(1024);
	var p = new Uint8Array(ret);
	var q = new Uint8Array(_tmpl.buffer);
	p.set(q);
	var i;
	for (i = 0; i < p.length - 4; i++)
		if (p[i] == 0xef && p[i+1] == 0xbe && p[i+2] == 0xad && p[i+3] == 0xde) {
			p[i] = v & 0xff;
			p[i+1] = (v >> 8) & 0xff;
			p[i+2] = (v >> 16) & 0xff;
			p[i+3] = (v >> 24) & 0xff;
		}
	return ret;
}
 
