var fs = require('fs');
 
function main(args) {
    if (args.length <= 1) {
        console.error("Usage: " + args[0] + " [infile]");
        return -1;
    }
 
    var input = fs.createReadStream(args[1]);
    if (!input.good()) {
        console.error("Error opening '" + args[1] + "'. Bailing out.");
        return -1;
    }
 
    var line, name, content;
    while (line = input.readLine()) {
        if (line.empty() || line[0] == '>') { // Identifier marker
            if (!name.empty()) { // Print out what we read from the last entry
                console.log(name + " : " + content);
                name.clear();
            }
            if (!line.empty()) {
                name = line.substr(1);
            }
            content.clear();
        } else if (!name.empty()) {
            if (line.find(' ')!= std::string::npos) { // Invalid sequence--no spaces allowed
                name.clear();
                content.clear();
            } else {
                content += line;
            }
        }
    }
    if (!name.empty()) { // Print out what we read from the last entry
        console.log(name + " : " + content);
    }
 
    return 0;
}
 
