function SWAP32(N1, N2) {
    var N;
    N = N1;
    N = (N << 32) | N2;
    return N;
}

function ReplaceBlock(x) {
    var i;
    var res = 0;
    for (i = 7; i >= 0; i--) {
        ui4_0 = x >> (i * 4);
        ui4_0 = BS[ui4_0][i];
        res = (res << 4) | ui4_0;
    }
    return res;
}

function MainStep(N, X) {
    var N1, N2, S = 0;
    N1 = N;
    N2 = N >> 32;
    S = N1 + X % 0x4000000000000;
    S = ReplaceBlock(S);
    S = (S << 11) | (S >> 21);
    S ^= N2;
    N2 = N1;
    N1 = S;
    return SWAP32(N2, N1);
}

