const fs = require('fs');
const path = require('path');
 
const readRules = (path) => {
    const ls = '\n';
    const lines = fs.readFileSync(path, 'utf8');
    const rules = [];
    for (const line of lines.split(ls + ls))
        rules.push(line.split(ls));
    return rules;
}
 
const readTests = (path) => {
    return fs.readFileSync(path, 'utf8').split('\n');
}
 
const rules = readRules(path.join(__dirname,'markov_rules.txt'));
const tests = readTests(path.join(__dirname,'markov_tests.txt'));
 
const pattern = /^([^#]*?)\s+->\s+(\.?)(.*)/;
 
for (let i = 0; i < tests.length; i++) {
    const origTest = tests[i];
 
    const captures = [];
    for (const rule of rules[i]) {
        const m = rule.match(pattern);
        if (m) {
            const groups = [];
            for (let j = 0; j < m.length; j++)
                groups[j] = m[j + 1];
            captures.push(groups);
        }
    }
 
    let test = origTest;
    let copy = test;
    for (let j = 0; j < captures.length; j++) {
        const c = captures[j];
        test = test.replace(c[0], c[2]);
        if (c[1] === '.')
            break;
        if (test!== copy) {
            j = -1; // redo loop
            copy = test;
        }
    }
    console.log(origTest);
    console.log(test);
    console.log();
}

