/*
Translate this

Note that this code is broken, e.g., it won't work when
blocks = [("A", "B"), ("A","C")] and the word is "AB", where the answer
should be True, but the code returns False.
*/
var blocks = [("B", "O"),
              ("X", "K"),
              ("D", "Q"),
              ("C", "P"),
              ("N", "A"),
              ("G", "T"),
              ("R", "E"),
              ("T", "G"),
              ("Q", "D"),
              ("F", "S"),
              ("J", "W"),
              ("H", "U"),
              ("V", "I"),
              ("A", "N"),
              ("O", "B"),
              ("E", "R"),
              ("F", "S"),
              ("L", "Y"),
              ("P", "C"),
              ("Z", "M")];
 
function can_make_word(word, block_collection) {
    if (block_collection === undefined) {
        block_collection = blocks;
    }
    if (!word) {
        return false;
    }
 
    var blocks_remaining = block_collection.slice();
    for (var i = 0; i < word.length; i++) {
        var char = word[i].toUpperCase();
        for (var j = 0; j < blocks_remaining.length; j++) {
            var block = blocks_remaining[j];
            if (block.indexOf(char)!== -1) {
                blocks_remaining.splice(j, 1);
                break;
            }
        }
        if (j === blocks_remaining.length) {
            return false;
        }
    }
    return true;
}
 
if (require.main === module) {
    var assert = require("assert");
    assert.equal(can_make_word(""), false);
    assert.equal(can_make_word("a"), true);
    assert.equal(can_make_word("bark"), true);
    assert.equal(can_make_word("book"), false);
    assert.equal(can_make_word("treat"), true);
    assert.equal(can_make_word("common"), false);
    assert.equal(can_make_word("squad"), true);
    assert.equal(can_make_word("Confused"), true);
    console.log(", ".join("'%s': %s" % (w, can_make_word(w)) for w in
                    ["", "a", "baRk", "booK", "treat",
                     "COMMON", "squad", "Confused"]));
}

