function CumulativeStandardDeviation() {
    this.n = 0;
    this.sum = 0;
    this.sum_sq = 0;
}
 
CumulativeStandardDeviation.prototype.push = function(x) {
    this.n += 1;
    this.sum += x;
    this.sum_sq += x * x;
 
    return Math.sqrt(this.sum_sq / this.n - this.sum * this.sum / this.n / this.n);
};
 
