var alloc = 0, n = 1;
var q = 0;
 
function qpush(h)
{
	var i, j;
	if (alloc <= n) {
		alloc = alloc? alloc * 2 : 16;
		q = realloc(q, sizeof(ham) * alloc);
	}
 
	for (i = n++; (j = i/2) && q[j] > h; q[i] = q[j], i = j);
	q[i] = h;
}
 
function qpop()
{
	var i, j;
	var r, t;
	/* outer loop for skipping duplicates */
	for (r = q[1]; n > 1 && r == q[1]; q[i] = t) {
		/* inner loop is the normal down heap routine */
		for (i = 1, t = q[--n]; (j = i * 2) < n;) {
			if (j + 1 < n && q[j] > q[j+1]) j++;
			if (t <= q[j]) break;
			q[i] = q[j], i = j;
		}
	}
 
	return r;
}
 
function main()
{
	var i;
	var h;
 
	for (qpush(i = 1); i <= 1691; i++) {
		/* takes smallest value, and queue its multiples */
		h = qpop();
		qpush(h * 2);
		qpush(h * 3);
		qpush(h * 5);
 
		if (i <= 20 || i == 1691)
			printf("%6d: %llu\n", i, h);
	}
 
	/* free(q); */
	return 0;
}

function numPrimeFactors(x) {
    var p = 2;
    var pf = 0;
    if (x == 1)
        return 1;
    else {
        while (true) {
            if (!(x % p)) {
                pf++;
                x /= p;
                if (x == 1)
                    return pf;
            }
            else
                ++p;
        }
    }
}
 
function primeFactors(x, arr) {
    var p = 2;
    var pf = 0;
    if (x == 1)
        arr[pf] = 1;
    else {
        while (true) {
            if (!(x % p)) {
                arr[pf++] = p;
                x /= p;
                if (x == 1)
                    return;
            }
            else
                p++;
        }
    }
}
 
function sumDigits(x) {
    var sum = 0, y;
    while (x) {
        y = x % 10;
        sum += y;
        x /= 10;
    }
    return sum;
}
 
function sumFactors(arr, size) {
    var sum = 0;
    for (var a = 0; a < size; a++)
        sum += sumDigits(arr[a]);
    return sum;
}
 
function listAllSmithNumbers(x) {
    var arr;
    for (var a = 4; a < x; a++) {
        var numfactors = numPrimeFactors(a);
        arr = new Array(numfactors);
        if (numfactors < 2)
            continue;	
        primeFactors(a, arr);	
        if (sumDigits(a) == sumFactors(arr,numfactors))
            console.log(a);
    }
}
 
