function pad_like(max_n=8, t=15) {
    var start = [[], [1, 1, 1]];
    for (var n = 2; n <= max_n; n++) {
        var this = start[n-1].slice(0, n+1);
        while (this.length < t) {
            this.push(this.slice(-2).reduce((a, b) => a + b));
        }
        start.push(this);
    }
    return start.slice(2);
}
 
