var BrownianTree = function() {
    this.I = new ImageData(400, 300);
    this.I.data[200 * 400 * 4 + 200 * 4 + 0] = 0xff;
    this.particles = [];
};
BrownianTree.prototype.run = function() {
    for (var i = 0; i < 20000; i++) {
        this.particles.push(new Particle());
    }
    while (this.particles.length > 0) {
        for (var i = 0; i < this.particles.length; i++) {
            if (this.particles[i].move()) {
                this.particles.splice(i, 1);
            }
        }
    }
};
BrownianTree.prototype.paint = function(ctx) {
    ctx.putImageData(this.I, 0, 0);
};
 
var Particle = function() {
    this.x = Math.floor(Math.random() * 400);
    this.y = Math.floor(Math.random() * 300);
};
Particle.prototype.move = function() {
    var dx = Math.floor(Math.random() * 3) - 1;
    var dy = Math.floor(Math.random() * 3) - 1;
    if ((this.x + dx < 0) || (this.y + dy < 0)
            || (this.y + dy >= 300) || (this.x + dx >= 400)) {
        return true;
    }
    this.x += dx;
    this.y += dy;
    if ((this.I.data[this.x * 400 * 4 + this.y * 4 + 0] & 0xff) == 0xff) {
        this.I.data[(this.x - dx) * 400 * 4 + (this.y - dy) * 4 + 0] = 0xff;
        return true;
    }
    return false;
};
 
