rl.on('line', function(line) {
    if (high === undefined) {
        high = parseInt(line);
    } else if (line === "") {
        rl.close();
    } else {
        var params = line.split(' ');
        var divisor = parseInt(params[0]);
        var word = params[1];
        entries.push([divisor, word]);
    }
});
 
rl.on('close', function() {
    for (var i = 1; i <= high; i++) {
        var line = "";
        for (var j = 0; j < entries.length; j++) {
            var entry = entries[j];
            if (i % entry[0] === 0) {
                line += entry[1];
            }
        }
        if (line === "") {
            console.log(i);
        } else {
            console.log(line);
        }
    }
});

