function parse_entry(entry, max_number) {
    const number = parseInt(entry);
    if (number < 1 || number > max_number) {
        throw new Error('Invalid entry');
    }
 
    return number;
}
 
function data_entry(prompt, terms) {
    if (terms.length === 0) {
        return '';
    }
 
    let choice;
    while (true) {
        print_menu(terms);
        rl.question(prompt, (entry) => {
            try {
                choice = parse_entry(entry, terms.length);
                rl.close();
                return terms[choice - 1];
            } catch (e) {
                console.log('Not a valid menu entry!');
            }
        });
    }
}
 
