function merge(x1, x2, y) {
	assert_eq(x1.length + x2.length, y.length);
	let i = 0;
	let j = 0;
	let k = 0;
	while (i < x1.length && j < x2.length) {
		if (x1[i] < x2[j]) {
			y[k] = x1[i];
			k += 1;
			i += 1;
		} else {
			y[k] = x2[j];
			k += 1;
			j += 1;
		}
	}
	if (i < x1.length) {
		y.set(x1.slice(i), k);
	}
	if (j < x2.length) {
		y.set(x2.slice(j), k);
	}
}

