function make_maze(w = 16, h = 8) {
    var vis = Array(h).fill(0).map(x => Array(w).fill(0).concat(1));
    vis.push(Array(w + 1).fill(1));
    var ver = Array(h).fill(0).map(x => Array(w).fill("|  ").concat("|"));
    ver.push([]);
    var hor = Array(h + 1).fill(0).map(x => Array(w).fill("+--").concat("+"));
 
    function walk(x, y) {
        vis[y][x] = 1;
 
        var d = [[x - 1, y], [x, y + 1], [x + 1, y], [x, y - 1]];
        shuffle(d);
        for (var i = 0; i < d.length; i++) {
            var xx = d[i][0];
            var yy = d[i][1];
            if (vis[yy][xx]) continue;
            if (xx == x) hor[Math.max(y, yy)][x] = "+  ";
            if (yy == y) ver[y][Math.max(x, xx)] = "   ";
            walk(xx, yy);
        }
    }
 
    walk(randrange(w), randrange(h));
 
    var s = "";
    for (var i = 0; i < hor.length; i++) {
        s += hor[i].join('') + '\n' + ver[i].join('') + '\n';
    }
    return s;
}

function Factors() {
    this.list = [];
    this.count = 0;
}
 
function xferFactors( fctrs, flist, flix ) 
{
    var ix, ij;
    var newSize = fctrs.count + flix;
    if (newSize > flix)  {
        fctrs.list = fctrs.list.slice(0, newSize);
    }
    else {
        fctrs.list = new Array(newSize);
    }
    for (ij=0,ix=fctrs.count; ix<newSize; ij++,ix++) {
        fctrs.list[ix] = flist[ij];
    }
    fctrs.count = newSize;
}
 
function factor( num, fctrs)
{
    var flist = new Array(301), flix;
    var dvsr;
    flix = 0;
    fctrs.count = 0;
    fctrs.list = [];
    for (dvsr=1; dvsr*dvsr < num; dvsr++) {
        if (num % dvsr!= 0) continue;
        if ( flix == 300) {
            xferFactors( fctrs, flist, flix );
            flix = 0;
        }
        flist[flix++] = dvsr;
        flist[flix++] = num/dvsr;
    }
    if (dvsr*dvsr == num) 
        flist[flix++] = dvsr;
    if (flix > 0)
        xferFactors( fctrs, flist, flix );
 
    return fctrs;
}
 
