var degrees06 = Math.PI / 30;
var degrees30 = degrees06 * 5;
var degrees90 = degrees30 * 3;
 
var margin = 20;
 
var p0;
 
function Clock() {
    this.Size = new Size(500, 500);
    this.StartPosition = FormStartPosition.CenterScreen;
    this.Resize += function (sender, args) {
        ResetSize();
    };
    ResetSize();
    var timer = new Timer();
    timer.Interval = 1000;
    timer.Enabled = true;
    timer.Tick += function (sender, e) {
        this.Refresh();
    };
    this.DoubleBuffered = true;
}
 
function ResetSize() {
    p0 = new Point(this.ClientRectangle.Width / 2, this.ClientRectangle.Height / 2);
    this.Refresh();
}
 
Clock.prototype.OnPaint = function (e) {
    e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
 
    drawFace(e.Graphics);
 
    var time = new Date();
    var second = time.getSeconds();
    var minute = time.getMinutes();
    var hour = time.getHours();
 
    var angle = degrees90 - (degrees06 * second);
    DrawHand(e.Graphics, Pens.Red, angle, 0.95);
 
    var minsecs = (minute + second / 60.0);
    angle = degrees90 - (degrees06 * minsecs);
    DrawHand(e.Graphics, Pens.Black, angle, 0.9);
 
    var hourmins = (hour + minsecs / 60.0);
    angle = degrees90 - (degrees30 * hourmins);
    DrawHand(e.Graphics, Pens.Black, angle, 0.6);
};
 
function drawFace(g) {
    var radius = Math.min(p0.X, p0.Y) - margin;
    g.FillEllipse(Brushes.White, p0.X - radius, p0.Y - radius, radius * 2, radius * 2);
 
    for (var h = 0; h < 12; h++)
        DrawHand(g, Pens.LightGray, h * degrees30, -0.05);
 
    for (var m = 0; m < 60; m++)
        DrawHand(g, Pens.LightGray, m * degrees06, -0.025);
}
 
function DrawHand(g, pen, angle, size) {
    var radius = Math.min(p0.X, p0.Y) - margin;
 
    var x0 = p0.X + (size > 0? 0 : radius * (1 + size) * Math.cos(angle));
    var y0 = p0.Y + (size > 0? 0 : radius * (1 + size) * Math.sin(-angle));
 
    var x1 = p0.X + radius * (size > 0? size : 1) * Math.cos(angle);
    var y1 = p0.Y + radius * (size > 0? size : 1) * Math.sin(-angle);
 
    g.DrawLine(pen, x0, y0, x1, y1);
}
 
function Main() {
    Application.Run(new Clock());
}
 
Main();

function partition(mask) {
  if (mask.length === 0) {
    return [[]];
  }
  var perms = [];
  var sum = mask.reduce(function(a, b) { return a + b; });
  for (var i = 1; i <= sum; i++) {
    perms.push(i);
  }
  return perms.reduce(function(a, b) { return a + b; }).permutation().map(function(perm) {
    return mask.map(function(num_elts) {
      return perm.shift(num_elts).sort();
    });
  }).uniq();
}

function TimeStr(sec) {
	var res = "";
	var wks = Math.floor(sec / 604800);
	sec = sec % 604800;
	var ds = Math.floor(sec / 86400);
	sec = sec % 86400;
	var hrs = Math.floor(sec / 3600);
	sec = sec % 3600;
	var mins = Math.floor(sec / 60);
	sec = sec % 60;
	var CommaRequired = false;
	if (wks!= 0) {
		res += wks + " wk";
		CommaRequired = true;
	}
	if (ds!= 0) {
		if (CommaRequired) {
			res += ", ";
		}
		res += ds + " d";
		CommaRequired = true;
	}
	if (hrs!= 0) {
		if (CommaRequired) {
			res += ", ";
		}
		res += hrs + " hr";
		CommaRequired = true;
	}
	if (mins!= 0) {
		if (CommaRequired) {
			res += ", ";
		}
		res += mins + " min";
		CommaRequired = true;
	}
	if (sec!= 0) {
		if (CommaRequired) {
			res += ", ";
		}
		res += sec + " sec";
	}
	return res;
}
 
