function Sort(list) {
    if (list.Count > 1) {
        StoogeSort(list, 0, list.Count - 1);
    }
}
function StoogeSort(L, i, j) {
    if (L[j].CompareTo(L[i]) < 0) {
        var tmp = L[i];
        L[i] = L[j];
        L[j] = tmp;
    }
    if (j - i > 1) {
        var t = (j - i + 1) / 3;
        StoogeSort(L, i, j - t);
        StoogeSort(L, i + t, j);
        StoogeSort(L, i, j - t);
    }
}

