function fractran( p, s, l )
{
    this.start = s; this.limit = l;
    var tmp = p.split( " " );
    var v = [];
    for( var i = 0; i < tmp.length; i++ )
    {
	var pos = tmp[i].indexOf( '/' );
	if( pos!= -1 )
	{
	    v.push( [ parseFloat( tmp[i].substr( 0, pos ) ), parseFloat( tmp[i].substr( pos + 1 ) ) ] );
	}
    }
    this.exec( v );
}
 
fractran.prototype.exec = function( v )
{
    var cnt = 0;
    while( cnt < this.limit )
    {
	console.log( cnt + " : " + this.start );
	cnt++;
	var found = false; var r;
	for( var i = 0; i < v.length; i++ )
	{
	    r = this.start * ( v[i][0] / v[i][1] );
	    if( r == Math.floor( r ) )
	    {
		found = true;
		break;
	    }
	}
 
	if( found ) this.start = Math.floor( r );
	else break;
    }
}
 
