// Code available at https://rosettacode.org/wiki/Linear_congruential_generator#JavaScript
 
// We can't use `Math.random` because it uses the more uniform `Math.random`
// (`% range` is subject to modulo bias).  If an exact match of the old dealer is not needed,
// `Math.random` should be used.
function shuffle(deck) {
    const len = deck.length;
    for (let i = len - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [deck[i], deck[j]] = [deck[j], deck[i]];
    }
}
 
function gen_deck() {
    const RANKS = ['A','2','3','4','5','6','7','8','9','T','J','Q','K'];
    const SUITS = ['C', 'D', 'H', 'S'];
 
    const render_card = (card) => {
        const suit = card % 4;
        const rank = card / 4;
        return `${RANKS[rank]}${SUITS[suit]}`;
    };
 
    return Array.from({length: 52}, (_, i) => render_card(i));
}
 
function deal_ms_fc_board(seed) {
    const deck = gen_deck();
 
    Math.seedrandom(seed);
    shuffle(deck);
    deck.reverse();
 
    return deck.map((card, i) => `${i % 8 === 0? ':':''} ${card}`).join('');
}
 
