function pangram(s) {
	var missing = (1 << 26) - 1;
	for (var i = 0; i < s.length; i++) {
		var c = s.charCodeAt(i);
		var index;
		if ('a' <= c && c <= 'z') {
			index = c - 'a'.charCodeAt(0);
		} else if ('A' <= c && c <= 'Z') {
			index = c - 'A'.charCodeAt(0);
		} else {
			continue;
		}
 
		missing &= ~(1 << index);
		if (missing == 0) {
			return true;
		}
	}
	return false;
}
 
