function get_new_state(windowed) {
    if (windowed[0] && windowed[1] &&!windowed[2]) {
        return true;
    } else if (!windowed[0] && windowed[1] && windowed[2]) {
        return true;
    } else {
        return false;
    }
}
 
function next_gen(cell) {
    let v = [];
    v.push(cell[0]);
    for (let i = 0; i < cell.length - 2; i++) {
        v.push(get_new_state([cell[i], cell[i + 1], cell[i + 2]]));
    }
    v.push(cell[cell.length - 1]);
    cell.splice(0, cell.length,...v);
}
 
