function mtest(m) {
    // the function finds odd prime factors by
    // searching no farther than sqrt(N), where N = 2^m-1.
    // the first odd prime is 3, 3^2 = 9, so M3 = 7 is still too small.
    // M4 = 15 is first number for which test is meaningful.
    if (m < 4) {
        console.log(m + " < 4.  M" + m + " not tested.");
        return;
    }
    var flimit = Math.sqrt(Math.pow(2, m) - 1);
    var qlast;
    if (flimit < qlimit) {
        qlast = flimit;
    } else {
        qlast = qlimit;
    }
    var composite = new Array(qlast + 1);
    var sq = Math.sqrt(qlast);
    loop:
    for (var q = 3; ; ) {
        if (q <= sq) {
            for (var i = q * q; i <= qlast; i += q) {
                composite[i] = true;
            }
        }
        if (q8 = q % 8, (q8 == 1 || q8 == 7) && modPow(2, m, q) == 1) {
            console.log("M" + m + " has factor " + q);
            return;
        }
        for (; ; ) {
            q += 2;
            if (q > qlast) {
                break loop;
            }
            if (!composite[q]) {
                break;
            }
        }
    }
    console.log("No factors of M" + m + " found.");
}
 
// base b to power p, mod m
function modPow(b, p, m) {
    var pow = 1;
    var b64 = b;
    var m64 = m;
    var bit = 30;
    for (1 << bit & p == 0) {
        bit--;
    }
    for (; ; ) {
        pow *= pow;
        if (1 << bit & p!= 0) {
            pow *= b64;
        }
        pow %= m64;
        if (bit == 0) {
            break;
        }
        bit--;
    }
    return pow;
}
 
// limit search to small primes.  really this is higher than
// you'd want it, but it's fun to factor M67.
var qlimit = 2e8;
 
mtest(31);
mtest(67);
mtest(929);

