function pShuffle(t) {
    var v, o, r, x, t2, c;
    v = [];
    o = [];
    r = [];
    for (x = 0; x < t; x++) {
        o.push(x + 1);
    }
    r = o;
    t2 = t / 2 - 1;
    c = 1;
    while (true) {
        v = r;
        r = [];
        for (x = t2; x > -1; x--) {
            r.push(v[x + t2 + 1]);
            r.push(v[x]);
        }
        r.reverse();
        if (o.equals(r)) {
            return c;
        }
        c++;
    }
}
 
