// --- thunks
function ARG(fn, k, x1, x2, x3, x4, x5) {
  this.fn = fn;
  this.k = k;
  this.x1 = x1;
  this.x2 = x2;
  this.x3 = x3;
  this.x4 = x4;
  this.x5 = x5;
}
 
// --- lambdas
function f_1(a) { return -1; }
function f0(a) { return 0; }
function f1(a) { return 1; }
 
// --- helper
function eval(a) { return a.fn(a); }
function MAKE_ARG(fn, k, x1, x2, x3, x4, x5) {
  return new ARG(fn, k, x1, x2, x3, x4, x5);
}
function FUN(a, x1, x2, x3, x4) {
  return MAKE_ARG(B, a.k, a, x1, x2, x3, x4);
}
 
function A(a) {
  return eval(a.x4) + eval(a.x5);
}
 
// --- functions
function B(a) {
  a.k.value -= 1;
  return A(FUN(a, a.x1, a.x2, a.x3, a.x4));
}
 
function main(k) {
  return A(FUN(MAKE_ARG(f1), MAKE_ARG(f_1), MAKE_ARG(f_1),
               MAKE_ARG(f1), MAKE_ARG(f0)));
}
 
// --- main
