var N = 5;
 
var lroots = new Array(N);
var weight = new Array(N);
var lcoef = new Array(N + 1);
for (var i = 0; i < N + 1; i++) {
    lcoef[i] = new Array(N + 1);
}
 
function legeCoef() {
    lcoef[0][0] = lcoef[1][1] = 1;
 
    for (var n = 2; n <= N; n++) {
 
        lcoef[n][0] = -(n - 1) * lcoef[n - 2][0] / n;
 
        for (var i = 1; i <= n; i++) {
            lcoef[n][i] = ((2 * n - 1) * lcoef[n - 1][i - 1]
                    - (n - 1) * lcoef[n - 2][i]) / n;
        }
    }
}
 
function legeEval(n, x) {
    var s = lcoef[n][n];
    for (var i = n; i > 0; i--)
        s = s * x + lcoef[n][i - 1];
    return s;
}
 
function legeDiff(n, x) {
    return n * (x * legeEval(n, x) - legeEval(n - 1, x)) / (x * x - 1);
}
 
function legeRoots() {
    var x, x1;
    for (var i = 1; i <= N; i++) {
        x = Math.cos(Math.PI * (i - 0.25) / (N + 0.5));
        do {
            x1 = x;
            x -= legeEval(N, x) / legeDiff(N, x);
        } while (x!= x1);
 
        lroots[i - 1] = x;
 
        x1 = legeDiff(N, x);
        weight[i - 1] = 2 / ((1 - x * x) * x1 * x1);
    }
}
 
function legeInte(f, a, b) {
    var c1 = (b - a) / 2, c2 = (b + a) / 2, sum = 0;
    for (var i = 0; i < N; i++)
        sum += weight[i] * f(c1 * lroots[i] + c2);
    return c1 * sum;
}
 
