function ditfft2(x, y, n, s) {
    if (n === 1) {
        y[0] = x[0];
        return;
    }
    ditfft2(x, y, n / 2, 2 * s);
    ditfft2(x.slice(s), y.slice(n / 2), n / 2, 2 * s);
    for (var k = 0; k < n / 2; k++) {
        var tf = Math.exp(-2 * Math.PI * k / n) * y[k + n / 2];
        y[k] = y[k] + tf;
        y[k + n / 2] = y[k] - tf;
    }
}
 
