function combSort(input) {
    var gap = input.length;
    if (gap <= 1) return; // already sorted
    var swaps = false;
    while (gap > 1 || swaps) {
        gap = Math.floor(gap / 1.247331);
        if (gap < 1) gap = 1;
        var i = 0;
        swaps = false;
        while (i + gap < input.length) {
            if (input[i] > input[i + gap]) {
                var tmp = input[i];
                input[i] = input[i + gap];
                input[i + gap] = tmp;
                swaps = true;
            }
            i++;
        }
    }
}
 
