function seq(n) {
    var s = n.toString();
    var ss = [s];
 
    while (true) {
        var dSeq = sortD(s);
        var d = dSeq[0];
        var nd = 1;
        s = "";
        for (var i = 1; ; i++) {
            if (i == dSeq.length) {
                s = s + nd + d;
                break;
            }
            if (dSeq[i] == d) {
                nd++;
            } else {
                s = s + nd + d;
                d = dSeq[i];
                nd = 1;
            }
        }
        for (var i = 0; i < ss.length; i++) {
            if (s == ss[i]) {
                return ss;
            }
        }
        ss.push(s);
    }
}
 
function sortD(s) {
    var r = [];
    for (var i = 0; i < s.length; i++) {
        var d = s[i];
        var j = 0;
        for (; j < i; j++) {
            if (d > r[j]) {
                r.splice(j, 0, d);
                break;
            }
        }
        r[j] = d;
    }
    return r;
}

