function abundantOdd(start, finish, listSize, printOne) {
    for (var oddNum = start; oddNum < finish; oddNum += 2) {
        list.length = 0;
        for (var toDivide = 1; toDivide < oddNum; toDivide+=2) {
            if (oddNum % toDivide == 0)
                list.push(toDivide);
        }
        if (sumList(list) > oddNum) {
            if(!printOne)
                console.log(oddNum + " <= " + sumList(list) );
            result.push(oddNum);
        }
        if(printOne && result.length >= listSize)
            console.log(oddNum + " <= " + sumList(list) );
 
        if(result.length >= listSize) break;
    }
}
 
function sumList(list) {
    var sum = 0;
    for (var i = 0; i < list.length; i++) {
        sum += list[i];
    }
    return sum;
}
 
