// version 1.1.2
 
function encode(s) {
    if (s.length === 0) return [];
    var symbols = "abcdefghijklmnopqrstuvwxyz".split("");
    var result = new Array(s.length);
    for (var i = 0; i < s.length; i++) {
        var c = s.charAt(i);
        var index = symbols.indexOf(c);
        if (index === -1) throw new Error(s + " contains a non-alphabetic character");
        result[i] = index;
        if (index === 0) continue;
        for (var j = index - 1; j >= 0; j--) symbols[j + 1] = symbols[j];
        symbols[0] = c;
    }
    return result;
}
 
function decode(a) {
    if (a.length === 0) return "";
    var symbols = "abcdefghijklmnopqrstuvwxyz".split("");
    var result = new Array(a.length);
    for (var i = 0; i < a.length; i++) {
        var n = a[i];
        if (n < 0 || n > 25) throw new Error(a + " contains an invalid number");
        result[i] = symbols[n];
        if (n === 0) continue;
        for (var j = n - 1; j >= 0; j--) symbols[j + 1] = symbols[j];
        symbols[0] = result[i];
    }
    return result.join("");
}
 
