    var row = 1;
    var diag = 0;
    for (var i = 0; i < this.ele.length; i++) {
        console.log(eleFmt, this.ele[i]);
        if (i == diag) {
            for (var j = diag + row, col = row; col < this.order; j += col) {
                console.log(eleFmt, this.ele[j]);
                col++;
            }
            console.log("\n");
            row++;
            diag += row;
        }
    }
};
 
var lower = function(order, ele) {
    this.order = order;
    this.ele = ele;
};
 
lower.prototype.print = function() {
    var eleFmt = "%10.5f ";
    var row = 1;
    var diag = 0;
    for (var i = 0; i < this.ele.length; i++) {
        console.log(eleFmt, this.ele[i]);
        if (i == diag) {
            for (var j = row; j < this.order; j++) {
                console.log(eleFmt, 0.);
            }
            console.log("\n");
            row++;
            diag += row;
        }
    }
};
 
symmetric.prototype.choleskyLower = function() {
    var l = new lower(this.order, this.ele.slice(0));
    var row = 1;
    var col = 1;
    var dr = 0;
    var dc = 0;
    for (var i = 0; i < this.ele.length; i++) {
        if (i < dr) {
            var d = (this.ele[i] - l.ele[i]) / l.ele[dc];
            l.ele[i] = d;
            var ci = col;
            var cx = dc;
            for (var j = i + 1; j <= dr; j++) {
                cx += ci;
                ci++;
                l.ele[j] += d * l.ele[cx];
            }
            col++;
            dc += col;
        } else {
            l.ele[i] = Math.sqrt(this.ele[i] - l.ele[i]);
            row++;
            dr += row;
            col = 1;
            dc = 0;
        }
    }
    return l;
};
 
var demo = function(a) {
    console.log("A:");
    a.print();
    console.log("L:");
    a.choleskyLower().print();
};
 
