// half adder with XOR and AND
// SUM = A XOR B
// CARRY = A.B
function half_adder(a, b) {
    return [a ^ b, a & b];
}
 
// full adder as a combination of half adders
// SUM = A XOR B XOR C
// CARRY = A.B + B.C + C.A
function full_adder(a, b, c_in) {
    var s0, c0, s1, c1;
    [s0, c0] = half_adder(a, b);
    [s1, c1] = half_adder(s0, c_in);
    return [s1, c0 | c1];
}
 
// A = (A3, A2, A1, A0)
// B = (B3, B2, B1, B0)
// S = (S3, S2, S1, S0)
function four_bit_adder(a, b) {
    // lets have a.0 refer to the rightmost element
    a = a.reverse();
    b = b.reverse();
 
    // i would prefer a loop but that would abstract
    // the "connections of the constructive blocks"
    var sum, carry;
    [sum, carry] = half_adder(a[0], b[0]);
    var out0 = sum;
    [sum, carry] = full_adder(a[1], b[1], carry);
    var out1 = sum;
    [sum, carry] = full_adder(a[2], b[2], carry);
    var out2 = sum;
    [sum, carry] = full_adder(a[3], b[3], carry);
    var out3 = sum;
    return [out3, out2, out1, out0];
}
 
function main() {
    var a = [0, 1, 1, 0];
    var b = [0, 1, 1, 0];
    assert_eq(four_bit_adder(a, b), [1, 1, 0, 0]);
    // 0110 + 0110 = 1100
    // 6 + 6 = 12
}
 
// misc. traits to make our life easier
function reverse(tuple) {
    return [tuple[3], tuple[2], tuple[1], tuple[0]];
}
 
// reverse a generic tuple of arity 4
function assert_eq(a, b) {
    if (a[0]!== b[0] || a[1]!== b[1] || a[2]!== b[2] || a[3]!== b[3]) {
        throw new Error("assertion failed");
    }
}
 
