var target = "METHINKS IT IS LIKE A WEASEL";
var validChars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ ";
var random = new java.util.Random();
 
function randomChar() {
    return validChars[random.nextInt(validChars.length)];
}
 
function hammingDistance(s1, s2) {
    return s1.split("").map(function(c, i) {
        return c == s2[i]? 0 : 1;
    }).reduce(function(a, b) {
        return a + b;
    });
}
 
function fitness(s1) {
    return target.length - hammingDistance(s1, target);
}
 
function mutate(s1, mutationRate) {
    return s1.split("").map(function(c) {
        return random.nextDouble() > mutationRate? c : randomChar();
    }).join("");
}
 
function main() {
    var initialString = (0).rangeTo(target.length).map(function(i) {
        return randomChar();
    }).join("");
 
    println(initialString);
    println(mutate(initialString, 0.2));
 
    var mutationRate = 0.05;
    var childrenPerGen = 50;
 
    var i = 0;
    var currVal = initialString;
    while (currVal!= target) {
        i += 1;
        currVal = (0).rangeTo(childrenPerGen).map(function(it) {
            return mutate(currVal, mutationRate);
        }).maxBy(function(it) {
            return fitness(it);
        });
    }
    println("Evolution found target after " + i + " generations");
}
 
