var MAX_D = 256;
var stack = new Array(MAX_D);
var depth = 0;
 
function push(v) {
	if (depth >= MAX_D) die("stack overflow\n");
	stack[depth++] = v;
}
 
function pop() {
	if (!depth) die("stack underflow\n");
	return stack[--depth];
}
 
function rpn(s) {
	var a, b, i, e, w = " \t\n\r\f";
	for (s = s.split(w); s.length; s = s.slice(1)) {
		a = parseFloat(s[0]);
		if (a.toString() == s[0]) {
			console.log(" :"), push(a);
#define binop(x) console.log("%c:", s[0]), b = pop(), a = pop(), push(x)
		} else if (s[0] == '+')	binop(a + b);
		else if (s[0] == '-')	binop(a - b);
		else if (s[0] == '*')	binop(a * b);
		else if (s[0] == '/')	binop(a / b);
		else if (s[0] == '^')	binop(Math.pow(a, b));
#undef binop
		else {
			console.log("'%c': ", s[0]);
			die("unknown oeprator\n");
		}
		for (i = depth; i-- || 0 * console.log('\n'); )
			console.log(" %g", stack[i]);
	}
 
	if (depth!= 1) die("stack leftover\n");
 
	return pop();
}
 
