const out = console.log;
const range = (start, end) => Array.from({length: (end - start)}, (v, k) => k + start);
const binomialCoef = (n, k) => {
    let result = 1;
    for (let i = 1; i <= k; i++)
        result = result * (n - i + 1) / i;
    return result;
}
 
const pascal = (n, f) => range(0, n).map(i => f(i));
 
const pascalUpp = n => pascal(n, i => range(0, n).map(j => binomialCoef(j, i)));
 
const pascalLow = n => pascal(n, i => range(0, n).map(j => binomialCoef(i, j)));
 
const pascalSym = n => pascal(n, i => range(0, n).map(j => binomialCoef(i + j, i)));
 
const print = (label, result) => {
    out("\n" + label);
    for (let row of result) {
        row.forEach(i => out("%2d ", i));
        console.log();
    }
}
 
