    1099726829285419];
// NUMBERS = [33, 44, 55, 275]
 
function lowest_factor(n, _start=3) {
    if (n % 2 == 0) {
        return 2;
    }
    let search_max = Math.floor(Math.sqrt(n)) + 1;
    for (let i = _start; i < search_max; i += 2) {
        if (n % i == 0) {
            return i;
        }
    }
    return n;
}
 
function prime_factors(n, lowest) {
    let pf = [];
    while (n > 1) {
        pf.push(lowest);
        n = Math.floor(n / lowest);
        lowest = lowest_factor(n, Math.max(lowest, 3));
    }
    return pf;
}
 
function prime_factors_of_number_with_lowest_prime_factor(NUMBERS) {
    let low_factor = Math.max(...NUMBERS.map(lowest_factor));
    let number = NUMBERS.find(n => lowest_factor(n) === low_factor);
    let all_factors = prime_factors(number, low_factor);
    return [number, all_factors];
}
 
function main() {
    console.log('For these numbers:');
    console.log(' '+ NUMBERS.join('\n  '));
    let [number, all_factors] = prime_factors_of_number_with_lowest_prime_factor(NUMBERS);
    console.log(`    The one with the largest minimum prime factor is ${number}:`);
    console.log(`      All its prime factors in order are: ${all_factors}`);
}
 
