function matrixMul(A, B) {
    var TB = zip(B);
    return A.map(function(a) {
        return TB.map(function(b) {
            return a.reduce(function(s, ea, i) {
                return s + ea * b[i];
            }, 0);
        });
    });
}
 
function pivotize(m) {
    var n = m.length,
        ID = [];
    for (var j = 0; j < n; j++) {
        var row = j;
        for (var i = j + 1; i < n; i++) {
            if (Math.abs(m[i][j]) > Math.abs(m[row][j])) {
                row = i;
            }
        }
        if (j!= row) {
            var tmp = ID[j];
            ID[j] = ID[row];
            ID[row] = tmp;
        }
    }
    return ID;
}
 
function lu(A) {
    var n = A.length,
        L = [],
        U = [],
        P = pivotize(A),
        A2 = matrixMul(P, A);
    for (var j = 0; j < n; j++) {
        L[j] = [];
        U[j] = [];
        L[j][j] = 1.0;
        for (var i = 0; i <= j; i++) {
            var s1 = 0;
            for (var k = 0; k < i; k++) {
                s1 += U[k][j] * L[i][k];
            }
            U[i][j] = A2[i][j] - s1;
        }
        for (var i = j; i < n; i++) {
            var s2 = 0;
            for (var k = 0; k < j; k++) {
                s2 += U[k][j] * L[i][k];
            }
            L[i][j] = (A2[i][j] - s2) / U[j][j];
        }
    }
    return [L, U, P];
}
 
var a = [[1, 3, 5], [2, 4, 7], [1, 1, 0]];
lu(a).forEach(function(part) {
    console.log(part);
});
console.log();
