	console.log('n=' + n + ','+ name + 'nacci ->'+ Array.apply(null, Array(15)).map(function(x, i) { return fibber(i); }).join(' ') + '...');
}

var matrix = function(m) {
    this.m = m;
};
 
matrix.prototype.kroneckerProduct = function(m2) {
    var m = this.m.length;
    var n = this.m[0].length;
    var p = m2.m.length;
    var q = m2.m[0].length;
    var rtn = m * p;
    var ctn = n * q;
    var r = new Array(rtn);
    for (var i = 0; i < rtn; i++) {
        r[i] = new Array(ctn);
    }
    for (var i = 0; i < m; i++) {
        for (var j = 0; j < n; j++) {
            for (var k = 0; k < p; k++) {
                for (var l = 0; l < q; l++) {
                    r[p*i+k][q*j+l] = this.m[i][j] * m2.m[k][l];
                }
            }
        }
    }
    return new matrix(r);
};
 
matrix.prototype.kroneckerPower = function(n) {
    var pow = this;
    for (var i = 1; i < n; i++) {
        pow = pow.kroneckerProduct(this);
    }
    return pow;
};
 
matrix.prototype.print = function(text) {
    console.log(text, "fractal :\n");
    for (var i = 0; i < this.m.length; i++) {
        for (var j = 0; j < this.m[0].length; j++) {
            if (this.m[i][j] == 1) {
                process.stdout.write("*");
            } else {
                process.stdout.write(" ");
            }
        }
        console.log();
    }
    console.log();
};
 
var m1 = new matrix([[0, 1, 0], [1, 1, 1], [0, 1, 0]]);
m1.kroneckerPower(4).print("Vivsek");
 
var m2 = new matrix([[1, 1, 1], [1, 0, 1], [1, 1, 1]]);
m2.kroneckerPower(4).print("Sierpinski carpet");

