 Extra, Extra - Read All About It: Nearly All Binary Searches and Mergesorts are Broken.

code:
function binarySearch(a, value, low, high) {
    if (high < low) {
        return -1;
    }
    var mid = (low + high) / 2;
    if (a[mid] > value) {
        return binarySearch(a, value, low, mid - 1);
    } else if (a[mid] < value) {
        return binarySearch(a, value, mid + 1, high);
    }
    return mid;
}

