var N = 100000;
var p = new Array(N + 1);
 
function calc(n)
{
	p[n] = 0;
 
	for (var k = 1; k <= n; k++) {
		var d = n - k * (3 * k - 1) / 2;
		if (d < 0) break;
 
		if (k&1)p[n] += p[d];
		else	p[n] -= p[d];
 
		d -= k;
		if (d < 0) break;
 
		if (k&1)p[n] += p[d];
		else	p[n] -= p[d];
	}
}
 
function main()
{
	var idx = [ 23, 123, 1234, 12345, 20000, 30000, 40000, 50000, N, 0 ];
	var at = 0;
 
	p[0] = 1;
 
	for (var i = 1; idx[at]; i++) {
		calc(i);
		if (i!= idx[at]) continue;
 
		console.log(i + ":\t" + p[i]);
		at++;
	}
}
 
main();

