var RockPaperScissorsGame = function() {
  this.CHOICES = ["rock", "paper", "scissors", "quit"];
  this.BEATS = {
    "rock": "paper",
    "paper": "scissors",
    "scissors": "rock"
  };
  this.plays = {
    "rock": 1,
    "paper": 1,
    "scissors": 1
  };
  this.score = [0, 0, 0];
  this.play();
};
 
RockPaperScissorsGame.prototype.humanPlay = function() {
  var answer, idx;
  while (true) {
    answer = prompt("Your choice: " + this.CHOICES + "? ");
    if (answer === "") {
      continue;
    }
    idx = this.CHOICES.findIndex(function(choice) {
      return choice.match("^" + answer);
    });
    if (idx!== -1) {
      return this.CHOICES[idx];
    }
    console.log("invalid answer, try again");
  }
};
 
RockPaperScissorsGame.prototype.computerPlay = function() {
  var c, r, sum, total;
  total = Object.values(this.plays).reduce(function(a, b) {
    return a + b;
  });
  r = Math.floor(Math.random() * total) + 1;
  sum = 0;
  for (c in this.CHOICES) {
    sum += this.plays[c];
    if (r <= sum) {
      return this.BEATS[c];
    }
  }
};
 
RockPaperScissorsGame.prototype.play = function() {
  var c, h;
  while (true) {
    h = this.humanPlay();
    if (h === "quit") {
      break;
    }
    c = this.computerPlay();
    console.log("H: " + h + ", C: " + c + " => ");
    this.plays[h] += 1;
    if (h === c) {
      console.log("draw");
      this.score[2] += 1;
    } else if (h === this.BEATS[c]) {
      console.log("Human wins");
      this.score[0] += 1;
    } else {
      console.log("Computer wins");
      this.score[1] += 1;
    }
    console.log("score: human=%d, computer=%d, draw=%d", this.score[0], this.score[1], this.score[2]);
  }
  Object.keys(this.plays).forEach(function(k) {
    return this.plays[k] -= 1;
  });
  console.log("humans chose " + this.plays);
};
 
new RockPaperScissorsGame();

