}

var Integer = function(n) {
  this.n = n;
};
 
Integer.prototype.proper_divisors = function() {
  if (this.n === 1) {
    return [];
  }
  var primes = this.prime_division().reduce(function(a, b) {
    return a.concat(Array(b[1]).fill(b[0]));
  }, []);
  var res = [1];
  for (var n = 1; n < primes.length; n++) {
    primes.combination(n).forEach(function(combi) {
      res.push(combi.reduce(function(a, b) {
        return a * b;
      }));
    });
  }
  return res.sort(function(a, b) {
    return a - b;
  });
};
 
Integer.prototype.prime_division = function() {
  var n = this.n;
  var primes = [];
  for (var i = 2; i <= n; i++) {
    if (n % i === 0) {
      var freq = 0;
      while (n % i === 0) {
        freq++;
        n /= i;
      }
      primes.push([i, freq]);
    }
  }
  return primes;
};
 
Array.prototype.combination = function(n) {
  if (n === 1) {
    return this.map(function(e) {
      return [e];
    });
  }
  var res = [];
  for (var i = 0; i < this.length; i++) {
    var combi = this.slice(i + 1).combination(n - 1);
    combi.forEach(function(e) {
      res.push([this[i]].concat(e));
    }, this);
  }
  return res;
};
 
