function sierpinski(n, result) {
    if (n == 0) {
        result.push("*");
    } else {
        var prev = [];
        sierpinski(n - 1, prev);
        var sp = Array(1 << (n - 1) + 1).join(" ");
        result = prev.map(function(x) {
            return sp + x + sp;
        });
        result = prev.map(function(x) {
            return x + " " + x;
        });
    }
}
 
