class Pixmap {
  constructor(width, height) {
    this.width = width;
    this.height = height;
    this.pixels = new Array(width * height);
  }

  static open(filename) {
    // TODO: implement
  }

  save(filename) {
    // TODO: implement
  }

  convolute(kernel) {
    const newimg = new Pixmap(this.width, this.height);
    const pb = new ProgressBar(this.width);
    for (let x = 0; x < this.width; x++) {
      for (let y = 0; y < this.height; y++) {
        this.apply_kernel(x, y, kernel, newimg);
      }
      pb.update(x);
    }
    pb.close();
    return newimg;
  }

  apply_kernel(x, y, kernel, newimg) {
    const x0 = x === 0? 0 : x - 1;
    const y0 = y === 0? 0 : y - 1;
    const x1 = x;
    const y1 = y;
    const x2 = x + 1 === this.width? x : x + 1;
    const y2 = y + 1 === this.height? y : y + 1;

    let r = 0.0;
    let g = 0.0;
    let b = 0.0;
    for (let xx = x0; xx <= x2; xx++) {
      for (let yy = y0; yy <= y2; yy++) {
        const k = kernel[xx - x0][yy - y0];
        const pixel = this.getPixel(xx, yy);
        r += k * pixel.r;
        g += k * pixel.g;
        b += k * pixel.b;
      }
    }
    newimg.setPixel(x, y, new RGBColour(this.luma(r), this.luma(g), this.luma(b)));
  }

  luma(value) {
    if (value < 0) {
      return 0;
    } else if (value > 255) {
      return 255;
    } else {
      return value;
    }
  }

  getPixel(x, y) {
    return this.pixels[y * this.width + x];
  }

  setPixel(x, y, pixel) {
    this.pixels[y * this.width + x] = pixel;
  }
}

class RGBColour {
  constructor(r, g, b) {
    this.r = r;
    this.g = g;
    this.b = b;
  }
}

