const hashJoin = (first, second) => {
  const hashMap = new Map();
 
  // hash phase
  for (const [key, valA] of second) {
    // collect all values by their keys, appending new ones to each existing entry
    const vals = hashMap.get(key) || [];
    vals.push(valA);
    hashMap.set(key, vals);
  }
 
  const result = [];
  // join phase
  for (const [key, valB] of first) {
    const vals = hashMap.get(key);
    if (vals) {
      for (const valA of vals) {
        result.push([valB, key, valA]);
      }
    }
  }
 
  return result;
};
 
