function valid_iban(iban) {
    // Ensure upper alphanumeric input.
    iban = iban.replace(' ','').replace('\t','');
    if (!iban.match(/^[\dA-Z]+$/)) {
        return false;
    }
    // Validate country code against expected length.
    if (iban.length!= _country2length[iban.substr(0,2)]) {
        return false;
    }
    // Shift and convert.
    iban = iban.substr(4) + iban.substr(0,4);
    var digits = parseInt(iban.replace(/[A-Z]/g, function(ch) { return parseInt(ch, 36); }), 10); //BASE 36: 0..9,A..Z -> 0..35
    return digits % 97 == 1;
}
 
