const bars = "▁▂▃▄▅▆▇█";
const n = bars.length - 1;
 
function toSparkline(iterable) {
    var min = Number.MAX_VALUE;
    var max = Number.MIN_VALUE;
    const doubles = Array.from(iterable).map(i => i.valueOf());
    doubles.forEach(i => {
        if (i < min) {
            min = i;
        }
        if (i > max) {
            max = i;
        }
    });
    const range = max - min;
    return doubles.reduce((line, d) => line + bars[Math.ceil((d - min) / range * n)], "");
}
 
function toSparklineString(s) {
    return toSparkline(s.replace(",", "").split(" ").map(i => parseFloat(i)));
}
 
