function PrecedenceLess(lhs, rhs, assoc) {
    var KNOWN = {
        "+": 1,
        "-": 1,
        "*": 2,
        "/": 2,
        "^": 3
    };
    var ASSOCIATIVE = ["+", "*"];
    return (KNOWN.hasOwnProperty(lhs)? KNOWN[lhs] : 0) < (KNOWN.hasOwnProperty(rhs)? KNOWN[rhs] : 0) + (assoc &&!ASSOCIATIVE.includes(rhs)? 1 : 0);
}
function Parenthesize(old, token, assoc) {
    if (old.op_.length > 0 && PrecedenceLess(old.op_, token, assoc)) {
        old.expr_ = "(" + old.expr_ + ")";
    }
}
function AddToken(stack, token) {
    if (token.indexOf("0123456789")!== -1) {
        stack.push({
            expr_: token,
            op_: ""
        });
    } else {
        if (stack.length < 2) {
            console.log("Stack underflow");
        }
        var rhs = stack[stack.length - 1];
        Parenthesize(rhs, token, false);
        stack.pop();
        var lhs = stack[stack.length - 1];
        Parenthesize(lhs, token, true);
        stack[stack.length - 1].expr_ = lhs.expr_ + " " + token + " " + rhs.expr_;
        stack[stack.length - 1].op_ = token;
    }
}
function ToInfix(src) {
    var stack = [];
    for (var start = src.begin(), p = src.begin(); ; ++p) {
        if (p == src.end() || *p == " ") {
            if (p > start) {
                AddToken(stack, String(start, p));
            }
            if (p == src.end()) {
                break;
            }
            start = p + 1;
        }
    }
    if (stack.length!= 1) {
        console.log("Incomplete expression");
    }
    return stack[stack.length - 1].expr_;
}
try {
    console.log(ToInfix("3 4 2 * 1 5 - 2 3 ^ ^ / +"));
    console.log(ToInfix("1 2 + 3 4 + ^ 5 6 + ^"));
} catch (e) {
    console.log("Failed");
}

