    function Gray() {
    }
    Gray.grayEncode = function (n) {
        return n ^ (n >> 1);
    };
    Gray.grayDecode = function (n) {
        var i = 1 << 8 * 64 - 2;
        var p, b = p = n & i;
        while ((i >>= 1) > 0) {
            b |= p = n & i ^ p >> 1;
        }
        return b;
    };
    Gray.Main = function (args) {
        console.log("Number\tBinary\tGray\tDecoded");
        for (var i = 0; i < 32; i++) {
