var LEN = function(x) { return x.length; };
 
var cd = function(name, population) {
    this.name = name;
    this.population = population;
};
 
var search_get_index_by_name = function(name, data, data_length, cmp_func) {
    var key = new cd(name, 0);
    var match = bsearch(key, data, data_length,
            sizeof(cd), cmp_func);
 
    if (match == null)
        return -1;
    else
        return ((match - data) / sizeof(cd));
};
 
var search_get_pop_by_name = function(name, data, data_length, cmp_func) {
    var key = new cd(name, 0);
    var match = lfind(key, data, data_length,
            sizeof(cd), cmp_func);
 
    if (match == null)
        return -1;
    else
        return match.population;
};
 
var search_get_pop_threshold = function(pop_threshold, data, data_length, cmp_func) {
    var key = new cd(null, pop_threshold);
    var match = lfind(key, data, data_length,
            sizeof(cd), cmp_func);
 
    if (match == null)
        return null;
    else
        return match.name;
};
 
var cd_nameChar_cmp = function(a, b) {
    var aa = a;
    var bb = b;
 
	var i,len = strlen(aa.name);
 
	for(i=0;i<len;i++)
		if(bb.name[i]!=aa.name[i])
			return -1;
	return 0;
};
 
var cd_name_cmp = function(a, b) {
    var aa = a;
    var bb = b;
    return strcmp(bb.name, aa.name);
};
 
var cd_pop_cmp = function(a, b) {
    var aa = a;
    var bb = b;
    return bb.population >= aa.population;
};
 
