function Main() {
    var rnum, tsum = 0.0;
    var random = new Random();
 
    for (var i = 0, rnum = 5.0; i < 7; i++, rnum += 1.0) {
        items[i].expect = 1.0 / rnum;
        tsum += items[i].expect;
    }
    items[7].expect = 1.0 - tsum;
 
    items[0].mapping = 1.0 / 5.0;
    for (var i = 1; i < 7; i++)
        items[i].mapping = items[i - 1].mapping + 1.0 / ((double)i + 5.0);
    items[7].mapping = 1.0;
 
    for (var i = 0; i < TRIALS; i++) {
        rnum = random.NextDouble();
        for (var j = 0; j < 8; j++)
            if (rnum < items[j].mapping) {
                items[j].probcount++;
                break;
            }
    }
 
    console.log("Trials: " + TRIALS);
    console.log("Items:          " + items[0].name.PadRight(9) + items[1].name.PadRight(9) + items[2].name.PadRight(9) + items[3].name.PadRight(9) + items[4].name.PadRight(9) + items[5].name.PadRight(9) + items[6].name.PadRight(9) + items[7].name.PadRight(9));
