    console.log("Attained prob.: " + (items[0].probcount / TRIALS).toFixed(6) + " " + (items[1].probcount / TRIALS).toFixed(6) + " " + (items[2].probcount / TRIALS).toFixed(6) + " " + (items[3].probcount / TRIALS).toFixed(6) + " " + (items[4].probcount / TRIALS).toFixed(6) + " " + (items[5].probcount / TRIALS).toFixed(6) + " " + (items[6].probcount / TRIALS).toFixed(6) + " " + (items[7].probcount / TRIALS).toFixed(6));
}
 
