function range_expand(range) {
    return range.split(',').reduce(function(acc, item) {
        var n = parseInt(item);
        if (n) {
            return acc.concat(n);
        }
        var dashpos = item.lastIndexOf('--');
        if (dashpos < 0) {
            dashpos = item.lastIndexOf('-');
        }
        var rstart = parseInt(item.slice(0, dashpos));
        var rend = parseInt(item.slice(dashpos + 1));
        return acc.concat(Array.apply(null, Array(rend - rstart + 1)).map(function(v, i) {
            return rstart + i;
        }));
    }, []);
}
 
