function divisors(n) {
    const divs = [1];
    const divs2 = [];
    let i = 2;
    while (i * i <= n) {
        if (n % i == 0) {
            const j = n / i;
            divs.push(i);
            if (i!= j) divs2.push(j);
        }
        i++;
    }
    divs2.push(...divs.reverse());
    return divs2;
}
 
function abundant(n, divs) {
    return divs.reduce((a, b) => a + b) > n;
}
 
function semiperfect(n, divs) {
    if (divs.length > 0) {
        const h = divs[0];
        const t = divs.slice(1);
        if (n < h) {
            return semiperfect(n, t);
        } else {
            return n == h || semiperfect(n-h, t) || semiperfect(n, t);
        }
    } else {
        return false;
    }
}
 
function sieve(limit) {
    // false denotes abundant and not semi-perfect.
    // Only interested in even numbers >= 2
    const w = new Array(limit).fill(false);
    for (let i = 2; i < limit; i += 2) {
        if (w[i]) continue;
        const divs = divisors(i);
        if (!abundant(i, divs)) {
            w[i] = true;
        } else if (semiperfect(i, divs)) {
            for (let j = i; j < limit; j += i) w[j] = true;
        }
    }
    return w;
}
 
function main() {
    const w = sieve(17000);
    let count = 0;
    const max = 25;
    console.log("The first 25 weird numbers are:");
    let n = 2;
    while (count < max) {
        if (!w[n]) {
            console.log(n);
            count++;
        }
        n += 2;
    }
}
 
