function expand(cp) {
    let out = "";
    for (let c of cp) {
        out += c === "N"? "north" :
            c === "E"? "east" :
            c === "S"? "south" :
            c === "W"? "west" :
            c === "b"? " by " :
            "-";
    }
    return out;
}
 
