var pi_digits = (function() {
  var q = 1, r = 0, t = 1, k = 1, n = 3, l = 3;
  return {
    next: function() {
      if (4*q+r-t < n*t) {
        var ret = n;
        var nr = 10*(r-n*t);
        n = ((10*(3*q+r)) / t) - 10*n;
        q *= 10;
        r = nr;
        return ret;
      } else {
        var nr = (2*q+r) * l;
        var nn = (q*(7*k+2)+r*l) / (t*l);
        q *= k;
        t *= l;
        l += 2;
        k += 1;
        n = nn;
        r = nr;
        return this.next();
      }
    }
  };
})();
 
