function egyptianDivide(dividend, divisor) {
    const pows = Array.from({length: 32}, (_, i) => 1 << i);
    const doublings = Array.from({length: 32}, (_, i) => divisor << i);
 
    const {answer, sum} = doublings
       .map((double, i) => [double, pows[i]])
       .reverse()
       .skipWhile(([i]) => i > dividend)
       .reduce(({answer, sum}, [double, power]) => {
            if (sum + double < dividend) {
                return {answer: answer + power, sum: sum + double};
            } else {
                return {answer, sum};
            }
        }, {answer: 0, sum: 0});
 
    return [answer, dividend - sum];
}
 
const [div, rem] = egyptianDivide(580, 34);
console.log(`580 divided by 34 is ${div} remainder ${rem}`);

// Version 1.2.40
 
class Point(var x: Int, var y: Int)
 
fun d2pt(n: Int, d: Int): Point {
    var x = 0
    var y = 0
    var t = d
    var s = 1
    while (s < n) {
        val rx = 1 and (t / 2)
        val ry = 1 and (t xor rx)
        val p = Point(x, y)
        rot(s, p, rx, ry)
        x = p.x + s * rx
        y = p.y + s * ry
        t /= 4
        s *= 2
    }
    return Point(x, y)
}
 
fun rot(n: Int, p: Point, rx: Int, ry: Int) {
    if (ry == 0) {
        if (rx == 1) {
            p.x = n - 1 - p.x
            p.y = n - 1 - p.y
        }
        val t  = p.x
        p.x = p.y
        p.y = t
    }
}
 
fun main(args:Array<String>) {
    val n = 32
    val k = 3
    val pts = List(n * k) { CharArray(n * k) {'' } }
    var prev = Point(0, 0)
    pts[0][0] = '.'
    for (d in 1 until n * n) {
        val curr = d2pt(n, d)
        val cx = curr.x * k
        val cy = curr.y * k
        val px = prev.x * k
        val py = prev.y * k
        pts[cx][cy] = '.'
        if (cx == px ) {
            if (py < cy)
                for (y in py + 1 until cy) pts[cx][y] = '|'
            else
                for (y in cy + 1 until py) pts[cx][y] = '|'
        }
        else {
            if (px < cx)
               for (x in px + 1 until cx) pts[x][cy] = '_'
            else
               for (x in cx + 1 until px) pts[x][cy] = '_'
        }
        prev = curr
    }
    for (i in 0 until n * k) {
        for (j in 0 until n * k) print(pts[j][i])
        println()
    }
}

function rrand(m) {
  return Math.floor(m * (Math.random() / (Math.random() + 1)));
}
 
function shuffle(obj, nmemb, size) {
  var temp = new Array(size);
  var n = nmemb;
  while (n > 1) {
    var k = rrand(n--);
    for (var i = 0; i < size; i++) {
      temp[i] = obj[n * size + i];
    }
    for (var i = 0; i < size; i++) {
      obj[n * size + i] = obj[k * size + i];
    }
    for (var i = 0; i < size; i++) {
      obj[k * size + i] = temp[i];
    }
  }
}

var TREE_LIST = [];
var OFFSET = [];
 
for (var i = 0; i <= 31; i++) {
    if (i === 1) {
        OFFSET.push(1);
    } else {
        OFFSET.push(0);
    }
}
 
function append(t) {
    TREE_LIST.push(1 | (t << 1));
}
 
function show(t, l) {
    while (l > 0) {
        l = l - 1;
        if (t % 2 === 1) {
            print('(');
        } else {
            print(')');
        }
        t = t >> 1;
    }
}
 
function listTrees(n) {
    for (var i = OFFSET[n]; i < OFFSET[n + 1]; i++) {
        show(TREE_LIST[i], n * 2);
        print("\n");
    }
}
 
function assemble(n, t, sl, pos, rem) {
    if (rem === 0) {
        append(t);
        return;
    }
 
    if (sl > rem) {
        sl = rem;
        pos = OFFSET[sl];
    } else if (pos >= OFFSET[sl + 1]) {
        sl = sl - 1;
        if (sl === 0) {
            return;
        }
        pos = OFFSET[sl];
    }
 
    assemble(n, t << (2 * sl) | TREE_LIST[pos], sl, pos, rem - sl);
    assemble(n, t, sl, pos + 1, rem);
}
 
function makeTrees(n) {
    if (OFFSET[n + 1]!== 0) {
        return;
    }
    if (n > 0) {
        makeTrees(n - 1);
    }
    assemble(n, 0, n - 1, OFFSET[n - 1], n - 1);
    OFFSET[n + 1] = TREE_LIST.length;
}
 
function test(n) {
    if (n < 1 || n > 12) {
        throw new Error("Argument must be between 1 and 12");
    }
 
    append(0);
 
    makeTrees(n);
    print("Number of %d-trees: %d\n", n, OFFSET[n + 1] - OFFSET[n]);
    listTrees(n);
}
 
test(5);

function base20(n, out) {
    var start = out;
    do {out[out.length] = n % 20;} while (n /= 20);
    var length = out.length - start.length;
 
    while (out.length > start.length) {
        var x = out.pop();
        out.unshift(start.shift());
        start.push(x);
    }
    return length;
}
 
function make_digit(n, place, line_length) {
    var parts = ["    ",".  ",".. ","... ","....","----"];
    var i;
 
    for (i=4; i>0; i--, n -= 5)
        place.splice(i*line_length, 0, parts[Math.max(0, Math.min(5, n))]);
 
    if (n == -20) place[4 * line_length + 1] = '@';
}
 
function mayan(n) {
    if (n == 0) return null; 
 
    var digits = [];
    var n_digits = base20(n, digits);
 
    var line_length = n_digits*5 + 2;
 
    var str = [];
    for (var i=0; i<line_length * 6; i++)
        str[i] ='';
 
    var ptr;
    var i;
    for (ptr=str, i=0; i<line_length; i+=5, ptr+=5) 
        ptr.splice(0, 0, "+----");
    ptr.splice(0, 0, "+\n");
    str.splice(5*line_length, 0, str.slice(0, line_length));
    for (ptr=str+line_length, i=0; i<line_length; i+=5, ptr+=5)
        ptr.splice(0, 0, "|    ");
    ptr.splice(0, 0, "|\n");
    str.splice(2*line_length, 0, str.slice(line_length, 2*line_length));
    str.splice(3*line_length, 0, str.slice(line_length, 3*line_length));
 
    for (i=0; i<n_digits; i++)
        make_digit(digits[i], str.slice(1+5*i, 1+5*i+line_length), line_length);
 
    return str.join('');
}
 
function main(argv) {
    if (argv.length!= 2) {
        console.log("usage: mayan <number>");
        return 1;
    }
    var i = parseInt(argv[1]);
    if (i <= 0) {
        console.log("number must be positive");
        return 1;
    }
    var m = mayan(i);
    console.log(m);
    return 0;
}
 
main(process.argv.slice(2));

import java.net.ServerSocket
import java.net.Socket
 
fun main() {
 
    fun handleClient(conn: Socket) {
        conn.use {
            val input = conn.inputStream.bufferedReader()
            val output = conn.outputStream.bufferedWriter()
 
            input.forEachLine { line ->
                output.write(line)
                output.newLine()
                output.flush()
            }
        }
    }
 
    ServerSocket(12321).use { listener ->
        while (true) {
            val conn = listener.accept()
            Thread { handleClient(conn) }.start()
        }
    }
}

var MAX = 15;
 
function count_divisors(n) {
    var i, count = 0;
    for (i = 1; i * i <= n; ++i) {
        if (!(n % i)) {
            if (i == n / i)
                count++;
            else
                count += 2;
        }
    }
    return count;
}
 
function main() {
    var i, k, n, seq = [];
    for (i = 0; i < MAX; ++i) seq[i] = 0;
    console.log("The first " + MAX + " terms of the sequence are:");
    for (i = 1, n = 0; n <  MAX; ++i) {
        k = count_divisors(i);
        if (k <= MAX && seq[k - 1] == 0) {
            seq[k - 1] = i;
            ++n;
        }
    }
    for (i = 0; i < MAX; ++i) console.log(seq[i]);
}
 
