function Frac(n, d) {
    if (d == 0) {
        throw new Error('d cannot be zero');
    }
 
    var nn = n;
    var dd = d;
    if (nn == 0) {
        dd = 1;
    } else if (dd < 0) {
        nn = -nn;
        dd = -dd;
    }
 
    var g = Math.abs(nn).gcd(Math.abs(dd));
    if (g > 1) {
        nn = nn / g;
        dd = dd / g;
    }
 
    this.num = nn;
    this.denom = dd;
}
 
Frac.prototype.toString = function() {
    if (this.denom == 1) {
        return this.num.toString();
    } else {
        return this.num + '/' + this.denom;
    }
};
 
Frac.prototype.neg = function() {
    return new Frac(-this.num, this.denom);
};
 
Frac.prototype.add = function(rhs) {
    return new Frac(this.num * rhs.denom + this.denom * rhs.num, rhs.denom * this.denom);
};
Frac.prototype.sub = function(rhs) {
    return new Frac(this.num * rhs.denom - this.denom * rhs.num, rhs.denom * this.denom);
};
 
Frac.prototype.mul = function(rhs) {
    return new Frac(this.num * rhs.num, rhs.denom * this.denom);
};
 
var FRAC_ZERO = new Frac(0, 1);
var FRAC_ONE  = new Frac(1, 1);
 
function bernoulli(n) {
    if (n < 0) {
        throw new Error('n cannot be negative');
    }
 
    var a = new Array(n + 1);
    a[0] = FRAC_ZERO;
 
    for (var m = 0; m <= n; m++) {
        a[m] = new Frac(1, m + 1);
        for (var j = m; j >= 1; j--) {
            a[j - 1] = a[j - 1].sub(a[j]).mul(new Frac(j, 1));
        }
    }
 
    if (n!= 1) {
        return a[0];
    }
    return a[0].neg();
}
 
function binomial(n, k) {
    if (n < 0) {
        throw new Error('n cannot be negative');
    }
    if (k < 0) {
        throw new Error('k cannot be negative');
    }
    if (n < k) {
        throw new Error('n cannot be less than k');
    }
 
    if (n == 0 || k == 0) {
        return 1;
    }
 
    var num = 1;
    for (var i = k + 1; i <= n; i++) {
        num = num * i;
    }
 
    var den = 1;
    for (var i = 2; i <= n - k; i++) {
        den = den * i;
    }
 
    return num / den;
}
 
function faulhaberTriangle(p) {
    var coeffs = new Array(p + 1);
    coeffs[0] = FRAC_ZERO;
    var q = new Frac(1, p + 1);
    var sign = -1;
    for (var j = 0; j <= p; j++) {
        sign = -sign;
        coeffs[p - j] = q.mul(new Frac(sign, 1)).mul(new Frac(binomial(p + 1, j), 1)).mul(bernoulli(j));
    }
    return coeffs;
}
 
function main() {
    for (var i = 0; i <= 9; i++) {
        var coeffs = faulhaberTriangle(i);
        for (var j = 0; j < coeffs.length; j++) {
            print(coeffs[j] +' ');
        }
        print('\n');
    }
}
 
main();

