const { shuffle } = require('lodash');
 
const Colour = {
    Black: 0,
    Red: 1,
};
 
function main() {
    //Create our deck.
    const deck = shuffle(
        Array(26).fill(Colour.Black)
       .concat(Array(26).fill(Colour.Red))
    );
 
    const blackStack = [];
    const redStack = [];
    const discarded = [];
 
    //Deal our cards.
    console.log('Discarding:', deck.map(c => c === Colour.Black? 'B' : 'R').join(' '));
    while (deck.length > 1) {
        const card = deck.pop();
        const next = deck.pop();
        switch (card) {
            case Colour.Red:
                redStack.push(next);
                break;
            case Colour.Black:
                blackStack.push(next);
                break;
        }
        discarded.push(card);
    }
 
    // Choose how many to swap.
    const max = Math.min(redStack.length, blackStack.length);
    const num = Math.floor(Math.random() * (max - 1)) + 1;
    console.log(`Exchanging ${num} cards`);
 
    // Actually swap our cards.
    for (let i = 0; i < num; i++) {
        const red = Math.floor(Math.random() * redStack.length);
        const black = Math.floor(Math.random() * blackStack.length);
        const temp = redStack[red];
        redStack[red] = blackStack[black];
        blackStack[black] = temp;
    }
 
    //Count how many are red and black.
    const numBlack = blackStack.filter(c => c === Colour.Black).length;
    const numRed = redStack.filter(c => c === Colour.Red).length;
 
    console.log(`Number of black cards in black stack: ${numBlack}`);
    console.log(`Number of red cards in red stack: ${numRed}`);
}
 
