fun gss(seq: IntArray): Triple<Int, Int, Int> {
    if (seq.isEmpty()) throw IllegalArgumentException("Array cannot be empty")
    var sum: Int
    var maxSum = seq[0]
    var first = 0
    var last = 0
    for (i in 1 until seq.size) {
        sum = 0
        for (j in i until seq.size) {
            sum += seq[j]
            if (sum > maxSum) {
                maxSum = sum
                first = i
                last = j
            }
        }
    }
    return Triple(maxSum, first, last)
}
 
fun main(args: Array<String>) {
  val seq = intArrayOf(-1, -2, 3, 5, 6, -2, -1, 4, -4, 2, -1)
  val(maxSum, first, last) = gss(seq)
  if (maxSum > 0) {
      println("Maximum subsequence is from indices $first to $last")
      print("Elements are : ")
      for (i in first.. last) print("${seq[i]} ")
      println("\nSum is $maxSum")
  }
  else
      println("Maximum subsequence is the empty sequence which has a sum of 0")
}

class ByteString(bytes) {
    constructor(bytes) {
        this.bytes = bytes;
    }
    get length() {
        return this.bytes.length;
    }
    isEmpty() {
        return this.bytes.length === 0;
    }
    plus(other) {
        return new ByteString(this.bytes.concat(other.bytes));
    }
    plus(byte) {
        return new ByteString(this.bytes.concat([byte]));
    }
    get(index) {
        if (index < 0 || index >= this.bytes.length) {
            throw new Error("Index out of range");
        }
        return this.bytes[index];
    }
    toByteArray() {
        return this.bytes;
    }
    copy() {
        return new ByteString(this.bytes.slice());
    }
    compareTo(other) {
        return this.toString().localeCompare(other.toString());
    }
    equals(other) {
        if (other == null ||!(other instanceof ByteString)) {
            return false;
        }
        return this.compareTo(other) === 0;
    }
    hashCode() {
        return this.toString().hashCode();
    }
    substring(startIndex) {
        return new ByteString(this.bytes.slice(startIndex));
    }
    substring(startIndex, endIndex) {
        return new ByteString(this.bytes.slice(startIndex, endIndex));
    }
    replace(oldByte, newByte) {
        const ba = new Array(this.length);
        for (let i = 0; i < this.length; i++) {
            ba[i] = this.bytes[i] === oldByte? newByte : this.bytes[i];
        }
        return new ByteString(ba);
    }
    replace(oldValue, newValue) {
        return this.toString().replace(oldValue.toString(), newValue.toString()).toByteString();
    }
    toString() {
        const chars = new Array(this.length);
        for (let i = 0; i < this.length; i++) {
            chars[i] = this.bytes[i] >= 0 && this.bytes[i] <= 127? String.fromCharCode(this.bytes[i]) : String.fromCharCode(this.bytes[i] + 256);
        }
        return chars.join("");
    }
}
function toByteString(str) {
    const bytes = new Array(str.length);
    for (let i = 0; i < str.length; i++) {
        bytes[i] = str.charCodeAt(i) >= 0 && str.charCodeAt(i) <= 127? str.charCodeAt(i) : str.charCodeAt(i) - 256;
    }
    return new ByteString(bytes);
}
Object.defineProperty(String.prototype, "bs", {
    get: function() {
        return toByteString(this);
    }
});
function main(args) {
    const ba = [65, 66, 67];
    const ba2 = [68, 69, 70];
    const bs = new ByteString(ba);
    const bs2 = new ByteString(ba2);
    const bs3 = bs.plus(bs2);
    const bs4 = "GHI£€".toByteString();
    console.log(`The length of ${bs} is ${bs.length}`);
    console.log(`${bs} + ${bs2} = ${bs3}`);
    console.log(`${bs} + D = ${bs.plus(68)}`);
    console.log(`${bs} == ABC is ${bs.equals(bs.copy())}`);
    console.log(`${bs} != ABC is ${!bs.equals(bs.copy())}`);
    console.log(`${bs} >= ${bs2} is ${bs.compareTo(bs2) >= 0}`);
    console.log(`${bs} <= ${bs2} is ${bs.compareTo(bs2) <= 0}`);
    console.log(`${bs} is ${bs.isEmpty()? "empty" : "not empty"}`);
    console.log(`ABC[1] = ${String.fromCharCode(bs.get(1))}`);
    console.log(`ABC as a byte array is ${bs.toByteArray().toString()}`);
    console.log(`ABCDEF(1..5) = ${bs3.substring(1)}`);
    console.log(`ABCDEF(2..4) = ${bs3.substring(2, 5)}`);
    console.log(`ABCDEF with C replaced by G is ${bs3.replace(67, 71)}`);
    console.log(`ABCDEF with CD replaced by GH is ${bs3.replace("CD".bs, "GH".bs)}`);
    console.log(`GHI£€ as a ByteString is ${bs4}`);
}
