function gnomeSort(a) {
    let len = a.length;
    let i = 1;
    let j = 2;
    while (i < len) {
        if (a[i - 1] <= a[i]) {
            // for descending sort, use >= for comparison
            i = j;
            j += 1;
        } else {
            let tmp = a[i - 1];
            a[i - 1] = a[i];
            a[i] = tmp;
            i -= 1;
            if (i == 0) {
                i = j;
                j += 1;
            }
        }
    }
}
 
