using System;
using System.Collections.Generic;
using System.Linq;
 
public class Program
{
    public static void Main() {
        var infix = "3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3";
        console.log(infix.toPostfix());
    }
}
 
public static class ShuntingYard
{
    private static readonly Dictionary<string, (string symbol, int precedence, bool rightAssociative)> operators
        = new (string symbol, int precedence, bool rightAssociative) [] {
            ("^", 4, true),
            ("*", 3, false),
            ("/", 3, false),
            ("+", 2, false),
            ("-", 2, false)
    }.ToDictionary(op => op.symbol);
 
    public static string ToPostfix(this string infix) {
        var tokens = infix.split(' ');
        var stack = new Stack<string>();
        var output = new List<string>();
        foreach (var token in tokens) {
            if (int.TryParse(token, out _)) {
                output.Add(token);
                print(token);
            } else if (operators.TryGetValue(token, out var op1)) {
                while (stack.Count > 0 && operators.TryGetValue(stack.Peek(), out var op2)) {
                    var c = op1.precedence.CompareTo(op2.precedence);
                    if (c < 0 ||!op1.rightAssociative && c <= 0) {
                        output.Add(stack.Pop());
                    } else {
                        break;
                    }
                }
                stack.Push(token);
                print(token);
            } else if (token == "(") {
                stack.Push(token);
                print(token);
            } else if (token == ")") {
                var top = "";
                while (stack.Count > 0 && (top = stack.Pop())!= "(") {
                    output.Add(top);
                }
                if (top!= "(") throw new ArgumentException("No matching left parenthesis.");
                print(token);
            }
        }
        while (stack.Count > 0) {
            var top = stack.Pop();
            if (!operators.ContainsKey(top)) throw new ArgumentException("No matching right parenthesis.");
            output.Add(top);
        }
        print("pop");
        return string.Join(" ", output);
 
        //Yikes!
        void print(string action) => console.log($"{action + ":",-4} {$"stack[ {string.Join(" ", stack.Reverse())} ]",-18} {$"out[ {string.Join(" ", output)} ]"}");
        //A little more readable?
        void print(string action) => console.log("{0,-4} {1,-18} {2}", action + ":", $"stack[ {string.Join(" ", stack.Reverse())} ]", $"out[ {string.Join(" ", output)} ]");
    }
}

var ZERO = new BigInteger("0");
var ONE = new BigInteger("1");
 
function Primes(n) {
    var res = [];
    var mod, div;
    for (var i = new BigInteger("2"); i.compareTo(n)!= 1; ) {
        div = n.divideAndRemainder(i);
        mod = div[1];
        while (mod.compareTo(ZERO) == 0) {
            res.push(i.clone());
            n = div[0];
            div = n.divideAndRemainder(i);
            mod = div[1];
        }
        i = i.add(ONE);
    }
    return res;
}
 
