const { shuffle, range, random } = require('lodash');
 
function playOptimal(n) {
    const secretList = shuffle(range(n));
 
    prisoner:
    for (let i = 0; i < secretList.length; ++i) {
        let prev = i;
        for (let j = 0; j < secretList.length / 2; ++j) {
            if (secretList[prev] === i) {
                continue prisoner;
            }
            prev = secretList[prev];
        }
        return false;
    }
    return true;
}
 
function playRandom(n) {
    const secretList = shuffle(range(n));
 
    prisoner:
    for (const i of secretList) {
        const trialList = shuffle(range(n));
 
        for (let j = 0; j < trialList.length / 2; ++j) {
            if (trialList[j] === i) {
                continue prisoner;
            }
        }
 
        return false;
    }
    return true;
}
 
function exec(n, p, play) {
    let succ = 0;
    for (let i = 0; i < n; ++i) {
        if (play(p)) {
            succ++;
        }
    }
    return (succ * 100.0) / n;
}
 
const n = 100_000;
const p = 100;
console.log(`# of executions: ${n}`);
console.log(`Optimal play success rate: ${exec(n, p, playOptimal)}%`);
console.log(`Random play success rate: ${exec(n, p, playRandom)}%`);

var dlNode = function(string) {
    this.string = string;
    this.next = null;
    this.prev = null;
};
 
var dlList = function() {
    this.head = null;
    this.tail = null;
};
 
dlList.prototype.toString = function() {
    if (this.head == null) {
        return this.head.toString();
    }
    var r = "[" + this.head.string;
    for (var p = this.head.next; p!= null; p = p.next) {
        r += " " + p.string;
    }
    return r + "]";
};
 
dlList.prototype.insertTail = function(node) {
    if (this.tail == null) {
        this.head = node;
    } else {
        this.tail.next = node;
    }
    node.next = null;
    node.prev = this.tail;
    this.tail = node;
};
 
dlList.prototype.insertAfter = function(existing, insert) {
    insert.prev = existing;
    insert.next = existing.next;
    existing.next.prev = insert;
    existing.next = insert;
    if (existing == this.tail) {
        this.tail = insert;
    }
};
 
var main = function() {
    var dll = new dlList();
    console.log(dll);
    var a = new dlNode("A");
    dll.insertTail(a);
    dll.insertTail(new dlNode("B"));
    console.log(dll);
    dll.insertAfter(a, new dlNode("C"));
    console.log(dll);
};
 
