function isSemordnilap(word) { return dict[dict[word]]; };
 
var semordnilaps = []
for (var key in dict) {
  if (isSemordnilap(key)) {
    var rev = dict[key];
    if (key < rev) {
      semordnilaps.push([key,rev]) ;
    }
  }
}
 
var count = semordnilaps.length;
