var R = [null, 1];
var S = [null, 2];
 
var extend_sequences = function (n) {
	var current = Math.max(R[R.length-1],S[S.length-1]);
	var i;
	while (R.length <= n || S.length <= n) {
		i = Math.min(R.length, S.length) - 1;
		current += 1;
		if (current === R[i] + S[i]) {
			R.push(current);
		} else {
			S.push(current);
		}
	}
}
 
var ffr = function(n) {
	extend_sequences(n);
	return R[n];
};
 
var ffs = function(n) {
	extend_sequences(n);
	return S[n];
};
 
